export type ToolType =
  | 'selection'
  | 'hand'
  | 'rectangle'
  | 'ellipse'
  | 'diamond'
  | 'line'
  | 'arrow'
  | 'freedraw'
  | 'text'
  | 'image'
  | 'eraser';

export type ElementType =
  | 'rectangle'
  | 'ellipse'
  | 'diamond'
  | 'line'
  | 'arrow'
  | 'freedraw'
  | 'text'
  | 'image';

export type FillStyle = 'hachure' | 'solid' | 'cross-hatch' | 'none';
export type StrokeStyle = 'solid' | 'dashed' | 'dotted';
export type Theme = 'light' | 'dark';

export interface Point {
  x: number;
  y: number;
}

export interface BoundBox {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ElementBase {
  id: string;
  type: ElementType;
  x: number;
  y: number;
  width: number;
  height: number;
  angle: number;
  strokeColor: string;
  backgroundColor: string;
  fillStyle: FillStyle;
  strokeWidth: number;
  strokeStyle: StrokeStyle;
  roughness: number;
  opacity: number;
  locked: boolean;
  groupIds: string[];
  seed: number;
  version: number;
  versionNonce: number;
  isDeleted: boolean;
  updated: number;
}

export interface ShapeElement extends ElementBase {
  type: 'rectangle' | 'ellipse' | 'diamond';
}

export interface LinearElement extends ElementBase {
  type: 'line' | 'arrow';
  points: Point[];
  startArrowhead: 'arrow' | 'bar' | 'dot' | null;
  endArrowhead: 'arrow' | 'bar' | 'dot' | null;
}

export interface FreedrawElement extends ElementBase {
  type: 'freedraw';
  points: Point[];
  pressures?: number[];
}

export interface TextElement extends ElementBase {
  type: 'text';
  text: string;
  fontSize: number;
  fontFamily: string;
  textAlign: 'left' | 'center' | 'right';
  verticalAlign: 'top' | 'middle' | 'bottom';
}

export interface ImageElement extends ElementBase {
  type: 'image';
  fileId: string;
  status: 'pending' | 'saved' | 'error';
}

export type ExcalidrawElement =
  | ShapeElement
  | LinearElement
  | FreedrawElement
  | TextElement
  | ImageElement;

export interface AppFile {
  id: string;
  dataURL: string;
  mimeType: string;
  created: number;
}

export interface AppState {
  theme: Theme;
  currentTool: ToolType;
  viewBackgroundColor: string;
