}

export interface RemotePointer {
  userId: string;
  userName: string;
  color: string;
  x: number;
  y: number;
  lastSeen: number;
}

export interface BoardDocument {
  type: 'excalidraw';
  version: number;
  source: string;
  elements: ExcalidrawElement[];
  appState: Partial<AppState>;
  files: Record<string, AppFile>;
}

export interface HistorySnapshot {
  elements: ExcalidrawElement[];
  selectedElementIds: Record<string, true>;
}

import { nanoid } from 'nanoid';

export function createId(prefix = 'el'): string {
  return `${prefix}_${nanoid(12)}`;
}

export function randomSeed(): number {
  return Math.floor(Math.random() * 2 ** 31);
}

import type { BoundBox, ExcalidrawElement, Point } from '@/types';

export const GRID_SIZE = 20;

export function snapToGrid(value: number, enabled: boolean, size = GRID_SIZE): number {
  if (!enabled) return value;
  return Math.round(value / size) * size;
}

export function rotatePoint(point: Point, center: Point, angle: number): Point {
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const dx = point.x - center.x;
  const dy = point.y - center.y;
  return {
    x: center.x + dx * cos - dy * sin,
    y: center.y + dx * sin + dy * cos,
  };
}

export function getElementCenter(element: ExcalidrawElement): Point {
  return {
    x: element.x + element.width / 2,
    y: element.y + element.height / 2,
  };
}

export function normalizeElementSize(element: ExcalidrawElement): ExcalidrawElement {
  let { x, y, width, height } = element;
  if (width < 0) {
    x += width;
    width = Math.abs(width);
  }
  if (height < 0) {
    y += height;
    height = Math.abs(height);
  }
  return { ...element, x, y, width, height };
}

export function getElementBounds(element: ExcalidrawElement): BoundBox {
  if (
    (element.type === 'line' || element.type === 'arrow' || element.type === 'freedraw') &&
    'points' in element &&
    element.points.length > 0
  ) {
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const p of element.points) {
      minX = Math.min(minX, element.x + p.x);
      minY = Math.min(minY, element.y + p.y);
      maxX = Math.max(maxX, element.x + p.x);
      maxY = Math.max(maxY, element.y + p.y);
    }
    const pad = element.strokeWidth;
    return {
      x: minX - pad,
      y: minY - pad,
      width: Math.max(1, maxX - minX + pad * 2),
      height: Math.max(1, maxY - minY + pad * 2),
    };
  }

  return {
    x: element.x,
    y: element.y,
    width: Math.abs(element.width) || 1,
    height: Math.abs(element.height) || 1,
  };
}

export function getCommonBounds(elements: ExcalidrawElement[]): BoundBox | null {
  if (!elements.length) return null;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const el of elements) {
    const b = getElementBounds(el);
    minX = Math.min(minX, b.x);
    minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.width);
    maxY = Math.max(maxY, b.y + b.height);
  }
  return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
}

export function hitTestElement(element: ExcalidrawElement, x: number, y: number): boolean {
  if (element.isDeleted || element.locked) return false;
  const bounds = getElementBounds(element);
  const pad = 8;
  const center = getElementCenter(element);

  let px = x;
  let py = y;
  if (element.angle) {
    const rotated = rotatePoint({ x, y }, center, -element.angle);
    px = rotated.x;
    py = rotated.y;
  }

  if (element.type === 'ellipse') {
    const cx = element.x + element.width / 2;
    const cy = element.y + element.height / 2;
    const rx = Math.abs(element.width) / 2 + pad;
    const ry = Math.abs(element.height) / 2 + pad;
    const nx = (px - cx) / rx;
    const ny = (py - cy) / ry;
    return nx * nx + ny * ny <= 1;
  }

  if (element.type === 'diamond') {
    const cx = element.x + element.width / 2;
    const cy = element.y + element.height / 2;
    const dx = Math.abs(px - cx) / (Math.abs(element.width) / 2 + pad);
    const dy = Math.abs(py - cy) / (Math.abs(element.height) / 2 + pad);
    return dx + dy <= 1;
  }

  if (
    (element.type === 'line' || element.type === 'arrow' || element.type === 'freedraw') &&
    'points' in element
  ) {
    for (let i = 0; i < element.points.length - 1; i++) {
      const a = {
        x: element.x + element.points[i].x,
        y: element.y + element.points[i].y,
      };
      const b = {
        x: element.x + element.points[i + 1].x,
        y: element.y + element.points[i + 1].y,
      };
      if (distanceToSegment({ x: px, y: py }, a, b) <= pad + element.strokeWidth) {
        return true;
      }
    }
    return false;
  }

  return (
    px >= bounds.x - pad &&
    px <= bounds.x + bounds.width + pad &&
    py >= bounds.y - pad &&
    py <= bounds.y + bounds.height + pad
  );
}

function distanceToSegment(p: Point, a: Point, b: Point): number {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  if (dx === 0 && dy === 0) return Math.hypot(p.x - a.x, p.y - a.y);
  const t = Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / (dx * dx + dy * dy)));
  return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
}

export function isPointInBox(point: Point, box: BoundBox): boolean {
  return (
    point.x >= box.x &&
    point.x <= box.x + box.width &&
    point.y >= box.y &&
    point.y <= box.y + box.height
  );
}

export function boxesIntersect(a: BoundBox, b: BoundBox): boolean {
  return !(
    a.x + a.width < b.x ||
    b.x + b.width < a.x ||
    a.y + a.height < b.y ||
    b.y + b.height < a.y
  );
}

export function screenToScene(
  clientX: number,
  clientY: number,
  scrollX: number,
  scrollY: number,
  zoom: number,
  rect: DOMRect,
): Point {
  return {
    x: (clientX - rect.left) / zoom - scrollX,
    y: (clientY - rect.top) / zoom - scrollY,
  };
}

export function sceneToScreen(
  x: number,
  y: number,
  scrollX: number,
  scrollY: number,
  zoom: number,
): Point {
  return {
    x: (x + scrollX) * zoom,
    y: (y + scrollY) * zoom,
  };
}

import type {
  AppState,
  ElementType,
  ExcalidrawElement,
  FreedrawElement,
  ImageElement,
  LinearElement,
  Point,
  ShapeElement,
  TextElement,
} from '@/types';
import { createId, randomSeed } from './id';
import { getElementBounds, normalizeElementSize } from './geometry';

export function createBaseProps(appState: AppState) {
  return {
    strokeColor: appState.strokeColor,
    backgroundColor: appState.backgroundColor,
    fillStyle: appState.fillStyle,
    strokeWidth: appState.strokeWidth,
    strokeStyle: appState.strokeStyle,
    roughness: appState.roughness,
    opacity: appState.opacity,
    locked: false,
    groupIds: [] as string[],
    seed: randomSeed(),
    version: 1,
    versionNonce: randomSeed(),
    isDeleted: false,
    updated: Date.now(),
    angle: 0,
  };
}

export function createShapeElement(
  type: 'rectangle' | 'ellipse' | 'diamond',
  x: number,
  y: number,
  appState: AppState,
): ShapeElement {
  return {
    id: createId(),
    type,
    x,
    y,
    width: 0,
    height: 0,
    ...createBaseProps(appState),
  };
}

export function createLinearElement(
  type: 'line' | 'arrow',
  x: number,
  y: number,
  appState: AppState,
): LinearElement {
  return {
    id: createId(),
    type,
    x,
    y,
    width: 0,
    height: 0,
    points: [
      { x: 0, y: 0 },
      { x: 0, y: 0 },
    ],
    startArrowhead: null,
    endArrowhead: type === 'arrow' ? 'arrow' : null,
    ...createBaseProps(appState),
  };
}

export function createFreedrawElement(x: number, y: number, appState: AppState): FreedrawElement {
  return {
    id: createId(),
    type: 'freedraw',
    x,
    y,
    width: 0,
    height: 0,
    points: [{ x: 0, y: 0 }],
    pressures: [0.5],
    ...createBaseProps(appState),
  };
}

export function createTextElement(
  x: number,
  y: number,
  text: string,
  appState: AppState,
): TextElement {
  const fontSize = appState.fontSize;
  const width = Math.max(40, text.length * fontSize * 0.55);
  const height = fontSize * 1.4;
  return {
    id: createId(),
    type: 'text',
    x,
    y,
    width,
    height,
    text,
    fontSize,
    fontFamily: 'Caveat, Virgil, cursive',
    textAlign: 'left',
    verticalAlign: 'top',
    ...createBaseProps(appState),
    backgroundColor: 'transparent',
  };
}

export function createImageElement(
  x: number,
  y: number,
  width: number,
  height: number,
  fileId: string,
  appState: AppState,
): ImageElement {
  return {
    id: createId(),
    type: 'image',
    x,
    y,
    width,
    height,
    fileId,
    status: 'saved',
    ...createBaseProps(appState),
    backgroundColor: 'transparent',
    strokeColor: 'transparent',
  };
}

export function duplicateElements(elements: ExcalidrawElement[], offset = 20): ExcalidrawElement[] {
  const idMap = new Map<string, string>();
  for (const el of elements) idMap.set(el.id, createId());

  return elements.map((el) => {
    const next: ExcalidrawElement = {
      ...structuredClone(el),
      id: idMap.get(el.id)!,
      x: el.x + offset,
      y: el.y + offset,
      seed: randomSeed(),
      version: 1,
      versionNonce: randomSeed(),
      updated: Date.now(),
      groupIds: el.groupIds.map((g) => {
        if (!idMap.has(g)) idMap.set(g, createId('grp'));
        return idMap.get(g)!;
      }),
    };
    return next;
  });
}

export function bumpVersion(element: ExcalidrawElement): ExcalidrawElement {
  return {
    ...element,
    version: element.version + 1,
    versionNonce: randomSeed(),
    updated: Date.now(),
  };
}

export function updateLinearFromPoints(element: LinearElement | FreedrawElement): typeof element {
  if (!element.points.length) return element;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const p of element.points) {
    minX = Math.min(minX, p.x);
    minY = Math.min(minY, p.y);
    maxX = Math.max(maxX, p.x);
    maxY = Math.max(maxY, p.y);
  }
  const offsetX = minX;
  const offsetY = minY;
  const points = element.points.map((p) => ({ x: p.x - offsetX, y: p.y - offsetY }));
  return {
    ...element,
    x: element.x + offsetX,
    y: element.y + offsetY,
    width: Math.max(1, maxX - minX),
    height: Math.max(1, maxY - minY),
    points,
  };
}

export function resizeElement(
  element: ExcalidrawElement,
  handle: string,
  dx: number,
  dy: number,
  keepAspect: boolean,
): ExcalidrawElement {
  let { x, y, width, height } = element;
  const aspect = width / (height || 1);

  switch (handle) {
    case 'n':
      y += dy;
      height -= dy;
      break;
    case 's':
      height += dy;
      break;
    case 'e':
      width += dx;
      break;
    case 'w':
      x += dx;
      width -= dx;
      break;
    case 'nw':
      x += dx;
      y += dy;
      width -= dx;
      height -= dy;
      break;
    case 'ne':
      y += dy;
      width += dx;
      height -= dy;
      break;
    case 'sw':
      x += dx;
      width -= dx;
      height += dy;
      break;
    case 'se':
      width += dx;
      height += dy;
      break;
  }

  if (keepAspect && (handle === 'nw' || handle === 'ne' || handle === 'sw' || handle === 'se')) {
    height = width / aspect;
    if (handle.includes('n')) y = element.y + element.height - height;
    if (handle.includes('w')) x = element.x + element.width - width;
  }

  if (Math.abs(width) < 4) width = width < 0 ? -4 : 4;
  if (Math.abs(height) < 4) height = height < 0 ? -4 : 4;

  let next = normalizeElementSize({ ...element, x, y, width, height });

  if (next.type === 'line' || next.type === 'arrow') {
    next = {
      ...next,
      points: [
        { x: 0, y: 0 },
        { x: next.width, y: next.height },
      ],
    };
  }

  return bumpVersion(next);
}

export function moveElements(elements: ExcalidrawElement[], dx: number, dy: number): ExcalidrawElement[] {
  return elements.map((el) =>
    el.locked
      ? el
      : bumpVersion({
          ...el,
          x: el.x + dx,
          y: el.y + dy,
        }),
  );
}

export function getSelectedElements(
  elements: ExcalidrawElement[],
  selectedIds: Record<string, true>,
): ExcalidrawElement[] {
  return elements.filter((el) => selectedIds[el.id] && !el.isDeleted);
}

export function measureText(text: string, fontSize: number, fontFamily: string): { width: number; height: number } {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  if (!ctx) return { width: text.length * fontSize * 0.55, height: fontSize * 1.4 };
  ctx.font = `${fontSize}px ${fontFamily}`;
  const lines = text.split('\n');
  let width = 0;
  for (const line of lines) {
    width = Math.max(width, ctx.measureText(line || ' ').width);
  }
  return {
    width: Math.max(20, width + 8),
    height: Math.max(fontSize * 1.2, lines.length * fontSize * 1.35),
  };
}

export function toolToElementType(tool: string): ElementType | null {
  switch (tool) {
    case 'rectangle':
    case 'ellipse':
    case 'diamond':
    case 'line':
    case 'arrow':
    case 'freedraw':
    case 'text':
    case 'image':
      return tool;
    default:
      return null;
  }
}

export function getVisibleElements(elements: ExcalidrawElement[]): ExcalidrawElement[] {
  return elements.filter((el) => !el.isDeleted);
}

export function elementsToBounds(elements: ExcalidrawElement[]) {
  return elements.map(getElementBounds);
}

export function deepCloneElements(elements: ExcalidrawElement[]): ExcalidrawElement[] {
  return structuredClone(elements);
}

const PALETTE = [
  '#1e1e1e',
  '#e03131',
  '#2f9e44',
  '#1971c2',
  '#f08c00',
  '#9c36b5',
  '#0c8599',
  '#ffffff',
];

const USER_COLORS = [
  '#e03131',
  '#2f9e44',
  '#1971c2',
  '#f08c00',
  '#9c36b5',
  '#0c8599',
  '#e64980',
  '#7048e8',
];

export function getStrokePalette(): string[] {
  return PALETTE;
}

export function getBgPalette(): string[] {
  return ['transparent', ...PALETTE];
}

export function randomUserColor(): string {
  return USER_COLORS[Math.floor(Math.random() * USER_COLORS.length)];
}

export function randomUserName(): string {
  const adjectives = ['Swift', 'Brave', 'Calm', 'Bright', 'Lucky', 'Clever', 'Quiet', 'Bold'];
  const animals = ['Fox', 'Owl', 'Bear', 'Wolf', 'Cat', 'Deer', 'Hawk', 'Panda'];
  const a = adjectives[Math.floor(Math.random() * adjectives.length)];
  const b = animals[Math.floor(Math.random() * animals.length)];
  return `${a} ${b}`;
}

import type { ExcalidrawElement, HistorySnapshot } from '@/types';
import { deepCloneElements } from '@/utils/elements';

export class HistoryManager {
  private undoStack: HistorySnapshot[] = [];
  private redoStack: HistorySnapshot[] = [];
  private maxSize = 200;

  clear() {
    this.undoStack = [];
    this.redoStack = [];
  }

  push(elements: ExcalidrawElement[], selectedElementIds: Record<string, true>) {
    this.undoStack.push({
      elements: deepCloneElements(elements),
      selectedElementIds: { ...selectedElementIds },
    });
    if (this.undoStack.length > this.maxSize) {
      this.undoStack.shift();
    }
    this.redoStack = [];
  }

  undo(
    currentElements: ExcalidrawElement[],
    currentSelected: Record<string, true>,
  ): HistorySnapshot | null {
    const prev = this.undoStack.pop();
    if (!prev) return null;
    this.redoStack.push({
      elements: deepCloneElements(currentElements),
      selectedElementIds: { ...currentSelected },
    });
    return prev;
  }

  redo(
    currentElements: ExcalidrawElement[],
    currentSelected: Record<string, true>,
  ): HistorySnapshot | null {
    const next = this.redoStack.pop();
    if (!next) return null;
    this.undoStack.push({
      elements: deepCloneElements(currentElements),
      selectedElementIds: { ...currentSelected },
    });
    return next;
  }

  canUndo() {
    return this.undoStack.length > 0;
  }

  canRedo() {
    return this.redoStack.length > 0;
  }
}

export const historyManager = new HistoryManager();

