  strokeStyle: 'solid',
  roughness: 1,
  opacity: 100,
  fontSize: 28,
  roomId: null,
  userName: randomUserName(),
  userColor: randomUserColor(),
};

interface BoardStore {
  elements: ExcalidrawElement[];
  files: Record<string, AppFile>;
  appState: AppState;
  remotePointers: Record<string, RemotePointer>;
  collaborators: Record<string, { userName: string; color: string }>;

  setTool: (tool: ToolType) => void;
  setTheme: (theme: 'light' | 'dark') => void;
  updateAppState: (partial: Partial<AppState>) => void;
  setElements: (elements: ExcalidrawElement[], pushHistory?: boolean) => void;
  replaceElements: (elements: ExcalidrawElement[]) => void;
  addElement: (element: ExcalidrawElement, pushHistory?: boolean) => void;
  updateElement: (id: string, updater: (el: ExcalidrawElement) => ExcalidrawElement, pushHistory?: boolean) => void;
  updateElements: (
    ids: string[],
    updater: (el: ExcalidrawElement) => ExcalidrawElement,
    pushHistory?: boolean,
  ) => void;
  deleteSelected: () => void;
  duplicateSelected: () => void;
  selectElements: (ids: string[], additive?: boolean) => void;
  clearSelection: () => void;
  moveSelected: (dx: number, dy: number, pushHistory?: boolean) => void;
  bringToFront: () => void;
  sendToBack: () => void;
  groupSelected: () => void;
  ungroupSelected: () => void;
  lockSelected: (locked: boolean) => void;
  setZoom: (zoom: number) => void;
  setScroll: (scrollX: number, scrollY: number) => void;
  undo: () => void;
  redo: () => void;
  addFile: (file: AppFile) => void;
  loadBoard: (payload: {
    elements: ExcalidrawElement[];
    files?: Record<string, AppFile>;
    appState?: Partial<AppState>;
  }) => void;
  setRemotePointer: (pointer: RemotePointer) => void;
  removeRemotePointer: (userId: string) => void;
  setCollaborators: (map: Record<string, { userName: string; color: string }>) => void;
  applyRemoteElements: (elements: ExcalidrawElement[]) => void;
  persist: () => void;
  hydrate: () => void;
  commitHistory: () => void;
}

function persistState(elements: ExcalidrawElement[], files: Record<string, AppFile>, appState: AppState) {
  try {
    const payload = {
      elements,
      files,
      appState: {
        theme: appState.theme,
        viewBackgroundColor: appState.viewBackgroundColor,
        gridMode: appState.gridMode,
        snapToGrid: appState.snapToGrid,
        showMinimap: appState.showMinimap,
        strokeColor: appState.strokeColor,
        backgroundColor: appState.backgroundColor,
        fillStyle: appState.fillStyle,
        strokeWidth: appState.strokeWidth,
        strokeStyle: appState.strokeStyle,
        roughness: appState.roughness,
        opacity: appState.opacity,
        fontSize: appState.fontSize,
        zoom: appState.zoom,
        scrollX: appState.scrollX,
        scrollY: appState.scrollY,
        userName: appState.userName,
        userColor: appState.userColor,
      },
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
  } catch {
    // ignore quota errors
  }
}

export const useBoardStore = create<BoardStore>((set, get) => ({
  elements: [],
  files: {},
  appState: defaultAppState,
  remotePointers: {},
  collaborators: {},

  setTool: (tool) =>
    set((s) => ({
      appState: {
        ...s.appState,
        currentTool: tool,
        selectedElementIds: tool === 'selection' ? s.appState.selectedElementIds : {},
      },
    })),

  setTheme: (theme) =>
    set((s) => {
      const viewBackgroundColor = theme === 'dark' ? '#121212' : '#ffffff';
      document.documentElement.classList.toggle('dark', theme === 'dark');
      return { appState: { ...s.appState, theme, viewBackgroundColor } };
    }),

  updateAppState: (partial) =>
    set((s) => ({ appState: { ...s.appState, ...partial } })),

  commitHistory: () => {
    const { elements, appState } = get();
    historyManager.push(elements, appState.selectedElementIds);
  },

  setElements: (elements, pushHistory = true) => {
    if (pushHistory) get().commitHistory();
    set({ elements });
    const s = get();
    persistState(elements, s.files, s.appState);
  },

  replaceElements: (elements) => {
    set({ elements });
    const s = get();
    persistState(elements, s.files, s.appState);
  },

  addElement: (element, pushHistory = true) => {
    if (pushHistory) get().commitHistory();
    set((s) => {
      const elements = [...s.elements, element];
      persistState(elements, s.files, s.appState);
      return {
        elements,
        appState: {
          ...s.appState,
          selectedElementIds: { [element.id]: true },
          currentTool: element.type === 'text' ? 'selection' : s.appState.currentTool,
        },
      };
    });
  },

  updateElement: (id, updater, pushHistory = false) => {
    if (pushHistory) get().commitHistory();
    set((s) => {
      const elements = s.elements.map((el) => (el.id === id ? bumpVersion(updater(el)) : el));
      persistState(elements, s.files, s.appState);
      return { elements };
    });
  },

  updateElements: (ids, updater, pushHistory = false) => {
    if (pushHistory) get().commitHistory();
    const idSet = new Set(ids);
    set((s) => {
      const elements = s.elements.map((el) => (idSet.has(el.id) ? bumpVersion(updater(el)) : el));
      persistState(elements, s.files, s.appState);
      return { elements };
    });
  },

  deleteSelected: () => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (!selected.length) return;
    get().commitHistory();
    const ids = new Set(selected.map((e) => e.id));
    set((s) => {
      const next = s.elements.map((el) =>
        ids.has(el.id) ? bumpVersion({ ...el, isDeleted: true }) : el,
      );
      persistState(next, s.files, s.appState);
      return {
        elements: next,
        appState: { ...s.appState, selectedElementIds: {} },
      };
    });
  },

  duplicateSelected: () => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (!selected.length) return;
    get().commitHistory();
    const copies = duplicateElements(selected);
    const selectedElementIds: Record<string, true> = {};
    for (const c of copies) selectedElementIds[c.id] = true;
    set((s) => {
      const next = [...s.elements, ...copies];
      persistState(next, s.files, s.appState);
      return {
        elements: next,
        appState: { ...s.appState, selectedElementIds },
      };
    });
  },

  selectElements: (ids, additive = false) =>
    set((s) => {
      const selectedElementIds: Record<string, true> = additive
        ? { ...s.appState.selectedElementIds }
        : {};
      for (const id of ids) selectedElementIds[id] = true;
      return { appState: { ...s.appState, selectedElementIds } };
    }),

  clearSelection: () =>
    set((s) => ({ appState: { ...s.appState, selectedElementIds: {} } })),

  moveSelected: (dx, dy, pushHistory = false) => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (!selected.length) return;
    if (pushHistory) get().commitHistory();
    const moved = moveElements(selected, dx, dy);
    const map = new Map(moved.map((e) => [e.id, e]));
    set((s) => {
      const next = s.elements.map((el) => map.get(el.id) ?? el);
      persistState(next, s.files, s.appState);
      return { elements: next };
    });
  },

  bringToFront: () => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (!selected.length) return;
    get().commitHistory();
    const ids = new Set(selected.map((e) => e.id));
    const rest = elements.filter((e) => !ids.has(e.id));
    const moved = elements.filter((e) => ids.has(e.id)).map(bumpVersion);
    set((s) => {
      const next = [...rest, ...moved];
      persistState(next, s.files, s.appState);
      return { elements: next };
    });
  },

  sendToBack: () => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (!selected.length) return;
    get().commitHistory();
    const ids = new Set(selected.map((e) => e.id));
    const rest = elements.filter((e) => !ids.has(e.id));
    const moved = elements.filter((e) => ids.has(e.id)).map(bumpVersion);
    set((s) => {
      const next = [...moved, ...rest];
      persistState(next, s.files, s.appState);
      return { elements: next };
    });
  },

  groupSelected: () => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (selected.length < 2) return;
    get().commitHistory();
    const groupId = createId('grp');
    const ids = new Set(selected.map((e) => e.id));
    set((s) => {
      const next = s.elements.map((el) =>
        ids.has(el.id)
          ? bumpVersion({ ...el, groupIds: [...el.groupIds, groupId] })
          : el,
      );
      persistState(next, s.files, s.appState);
      return { elements: next };
    });
  },

  ungroupSelected: () => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (!selected.length) return;
    get().commitHistory();
    const ids = new Set(selected.map((e) => e.id));
    set((s) => {
      const next = s.elements.map((el) =>
        ids.has(el.id) ? bumpVersion({ ...el, groupIds: [] }) : el,
      );
      persistState(next, s.files, s.appState);
      return { elements: next };
    });
  },

  lockSelected: (locked) => {
    const { elements, appState } = get();
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    if (!selected.length) return;
    get().commitHistory();
    const ids = new Set(selected.map((e) => e.id));
    set((s) => {
      const next = s.elements.map((el) =>
        ids.has(el.id) ? bumpVersion({ ...el, locked }) : el,
      );
      persistState(next, s.files, s.appState);
      return { elements: next };
    });
  },

  setZoom: (zoom) =>
    set((s) => ({
      appState: { ...s.appState, zoom: Math.min(8, Math.max(0.1, zoom)) },
    })),

  setScroll: (scrollX, scrollY) =>
    set((s) => ({ appState: { ...s.appState, scrollX, scrollY } })),

  undo: () => {
    const { elements, appState } = get();
    const prev = historyManager.undo(elements, appState.selectedElementIds);
    if (!prev) return;
    set((s) => {
      persistState(prev.elements, s.files, s.appState);
      return {
        elements: prev.elements,
        appState: { ...s.appState, selectedElementIds: prev.selectedElementIds },
      };
    });
  },

  redo: () => {
    const { elements, appState } = get();
    const next = historyManager.redo(elements, appState.selectedElementIds);
    if (!next) return;
    set((s) => {
      persistState(next.elements, s.files, s.appState);
      return {
        elements: next.elements,
        appState: { ...s.appState, selectedElementIds: next.selectedElementIds },
      };
    });
  },

  addFile: (file) =>
    set((s) => {
      const files = { ...s.files, [file.id]: file };
      persistState(s.elements, files, s.appState);
      return { files };
    }),

  loadBoard: ({ elements, files, appState }) => {
    historyManager.clear();
    set((s) => {
      const nextApp = { ...s.appState, ...appState, selectedElementIds: {} };
      const nextFiles = files ?? {};
      persistState(elements, nextFiles, nextApp);
      return {
        elements: deepCloneElements(elements),
        files: nextFiles,
        appState: nextApp,
      };
    });
  },

  setRemotePointer: (pointer) =>
    set((s) => ({
      remotePointers: { ...s.remotePointers, [pointer.userId]: pointer },
    })),

  removeRemotePointer: (userId) =>
    set((s) => {
      const remotePointers = { ...s.remotePointers };
      delete remotePointers[userId];
      return { remotePointers };
    }),

  setCollaborators: (map) => set({ collaborators: map }),

  applyRemoteElements: (elements) => {
    set((s) => {
      persistState(elements, s.files, s.appState);
      return { elements };
    });
  },

  persist: () => {
    const s = get();
    persistState(s.elements, s.files, s.appState);
  },

  hydrate: () => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      const data = JSON.parse(raw);
      set((s) => {
        const theme = data.appState?.theme ?? s.appState.theme;
        document.documentElement.classList.toggle('dark', theme === 'dark');
        return {
          elements: data.elements ?? [],
          files: data.files ?? {},
          appState: { ...s.appState, ...data.appState, selectedElementIds: {} },
        };
      });
    } catch {
      // ignore
    }
  },
}));

import rough from 'roughjs';
import type { RoughCanvas } from 'roughjs/bin/canvas';
import type { Options as RoughOptions } from 'roughjs/bin/core';
import type { AppFile, AppState, ExcalidrawElement, Point } from '@/types';
import { getCommonBounds, getElementBounds, getElementCenter, rotatePoint } from '@/utils/geometry';
import { getStroke } from 'perfect-freehand';

const imageCache = new Map<string, HTMLImageElement>();

function getRoughOptions(element: ExcalidrawElement): RoughOptions {
  const fill =
    element.backgroundColor === 'transparent' || element.fillStyle === 'none'
      ? undefined
      : element.backgroundColor;

  let fillStyle: RoughOptions['fillStyle'] = 'hachure';
  if (element.fillStyle === 'solid') fillStyle = 'solid';
  if (element.fillStyle === 'cross-hatch') fillStyle = 'cross-hatch';

  return {
    seed: element.seed,
    roughness: element.roughness,
    stroke: element.strokeColor,
    strokeWidth: element.strokeWidth,
    fill,
    fillStyle,
    strokeLineDash:
      element.strokeStyle === 'dashed'
        ? [12, 8]
        : element.strokeStyle === 'dotted'
          ? [2, 6]
          : undefined,
  };
}

function withOpacity(ctx: CanvasRenderingContext2D, opacity: number, draw: () => void) {
  const prev = ctx.globalAlpha;
  ctx.globalAlpha = prev * (opacity / 100);
  draw();
  ctx.globalAlpha = prev;
}

function drawArrowHead(
  ctx: CanvasRenderingContext2D,
  from: Point,
  to: Point,
  color: string,
  size: number,
) {
  const angle = Math.atan2(to.y - from.y, to.x - from.x);
  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(to.x, to.y);
  ctx.lineTo(
    to.x - size * Math.cos(angle - Math.PI / 6),
    to.y - size * Math.sin(angle - Math.PI / 6),
  );
  ctx.lineTo(
    to.x - size * Math.cos(angle + Math.PI / 6),
    to.y - size * Math.sin(angle + Math.PI / 6),
  );
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function getImage(file: AppFile): HTMLImageElement | null {
  const cached = imageCache.get(file.id);
  if (cached) return cached;
  const img = new Image();
  img.src = file.dataURL;
  imageCache.set(file.id, img);
  return img;
}

function renderElement(
  ctx: CanvasRenderingContext2D,
  rc: RoughCanvas,
  element: ExcalidrawElement,
  files: Record<string, AppFile>,
) {
  if (element.isDeleted) return;

  withOpacity(ctx, element.opacity, () => {
    ctx.save();
    const center = getElementCenter(element);
    if (element.angle) {
      ctx.translate(center.x, center.y);
      ctx.rotate(element.angle);
      ctx.translate(-center.x, -center.y);
    }

    const opts = getRoughOptions(element);

    switch (element.type) {
      case 'rectangle':
        rc.rectangle(element.x, element.y, element.width, element.height, opts);
        break;
      case 'ellipse':
        rc.ellipse(
          element.x + element.width / 2,
          element.y + element.height / 2,
          Math.abs(element.width),
          Math.abs(element.height),
          opts,
        );
        break;
      case 'diamond': {
        const cx = element.x + element.width / 2;
        const cy = element.y + element.height / 2;
        const hw = element.width / 2;
        const hh = element.height / 2;
        rc.polygon(
          [
            [cx, element.y],
            [element.x + element.width, cy],
            [cx, element.y + element.height],
            [element.x, cy],
          ],
          opts,
        );
        void hw;
        void hh;
        break;
      }
      case 'line':
      case 'arrow': {
        const pts = element.points.map((p) => [element.x + p.x, element.y + p.y] as [number, number]);
        if (pts.length >= 2) {
          rc.linearPath(pts, opts);
          if (element.type === 'arrow' && element.endArrowhead === 'arrow') {
            const a = { x: pts[pts.length - 2][0], y: pts[pts.length - 2][1] };
            const b = { x: pts[pts.length - 1][0], y: pts[pts.length - 1][1] };
            drawArrowHead(ctx, a, b, element.strokeColor, 12 + element.strokeWidth * 2);
          }
        }
        break;
      }
      case 'freedraw': {
        const input = element.points.map((p) => [element.x + p.x, element.y + p.y, 0.5]);
        const outline = getStroke(input, {
          size: element.strokeWidth * 3.5,
          thinning: 0.6,
          smoothing: 0.5,
          streamline: 0.5,
          easing: (t) => t,
          start: { taper: 0 },
          end: { taper: 20 },
        });
        if (outline.length) {
          ctx.fillStyle = element.strokeColor;
          ctx.beginPath();
          ctx.moveTo(outline[0][0], outline[0][1]);
          for (let i = 1; i < outline.length; i++) {
            ctx.lineTo(outline[i][0], outline[i][1]);
          }
          ctx.closePath();
          ctx.fill();
        }
        break;
      }
      case 'text': {
        ctx.fillStyle = element.strokeColor;
        ctx.font = `${element.fontSize}px ${element.fontFamily}`;
        ctx.textBaseline = 'top';
        const lines = element.text.split('\n');
        lines.forEach((line, i) => {
          let x = element.x;
          if (element.textAlign === 'center') {
            const w = ctx.measureText(line).width;
            x = element.x + (element.width - w) / 2;
          } else if (element.textAlign === 'right') {
            const w = ctx.measureText(line).width;
            x = element.x + element.width - w;
          }
          ctx.fillText(line, x, element.y + i * element.fontSize * 1.35);
        });
        break;
      }
      case 'image': {
        const file = files[element.fileId];
        if (file) {
          const img = getImage(file);
          if (img && img.complete) {
            ctx.drawImage(img, element.x, element.y, element.width, element.height);
          }
        }
        break;
      }
    }

    ctx.restore();
  });
}

function drawGrid(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  scrollX: number,
  scrollY: number,
  zoom: number,
  dark: boolean,
) {
  const step = 20 * zoom;
  const offsetX = ((scrollX * zoom) % step + step) % step;
  const offsetY = ((scrollY * zoom) % step + step) % step;
  ctx.save();
  ctx.strokeStyle = dark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = offsetX; x < width; x += step) {
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
  }
  for (let y = offsetY; y < height; y += step) {
    ctx.moveTo(0, y);
    ctx.lineTo(width, y);
  }
  ctx.stroke();
  ctx.restore();
}

function drawSelection(
  ctx: CanvasRenderingContext2D,
  elements: ExcalidrawElement[],
  selectedIds: Record<string, true>,
) {
  const selected = elements.filter((el) => selectedIds[el.id] && !el.isDeleted);
  if (!selected.length) return;

  const bounds = getCommonBounds(selected);
  if (!bounds) return;

  ctx.save();
  ctx.strokeStyle = '#6965db';
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 3]);
  ctx.strokeRect(bounds.x - 2, bounds.y - 2, bounds.width + 4, bounds.height + 4);
  ctx.setLineDash([]);

  if (selected.length === 1 && selected[0].angle) {
    const el = selected[0];
    const center = getElementCenter(el);
    ctx.translate(center.x, center.y);
    ctx.rotate(el.angle);
    ctx.translate(-center.x, -center.y);
  }

  const handles =
    selected.length === 1
      ? getResizeHandles(selected[0])
      : [
          { id: 'nw', x: bounds.x, y: bounds.y },
          { id: 'ne', x: bounds.x + bounds.width, y: bounds.y },
          { id: 'sw', x: bounds.x, y: bounds.y + bounds.height },
          { id: 'se', x: bounds.x + bounds.width, y: bounds.y + bounds.height },
        ];

  ctx.fillStyle = '#fff';
  ctx.strokeStyle = '#6965db';
  for (const h of handles) {
    ctx.beginPath();
    ctx.rect(h.x - 4, h.y - 4, 8, 8);
    ctx.fill();
    ctx.stroke();
  }

  // rotate handle
  const rx = bounds.x + bounds.width / 2;
  const ry = bounds.y - 24;
  ctx.beginPath();
  ctx.moveTo(bounds.x + bounds.width / 2, bounds.y);
  ctx.lineTo(rx, ry);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(rx, ry, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}

export function getResizeHandles(element: ExcalidrawElement) {
  const b = getElementBounds(element);
  return [
    { id: 'nw', x: b.x, y: b.y },
    { id: 'n', x: b.x + b.width / 2, y: b.y },
    { id: 'ne', x: b.x + b.width, y: b.y },
    { id: 'e', x: b.x + b.width, y: b.y + b.height / 2 },
    { id: 'se', x: b.x + b.width, y: b.y + b.height },
    { id: 's', x: b.x + b.width / 2, y: b.y + b.height },
    { id: 'sw', x: b.x, y: b.y + b.height },
    { id: 'w', x: b.x, y: b.y + b.height / 2 },
    { id: 'rotate', x: b.x + b.width / 2, y: b.y - 24 },
  ];
}

export function hitTestHandle(
  element: ExcalidrawElement,
  x: number,
  y: number,
): string | null {
  const center = getElementCenter(element);
  let px = x;
  let py = y;
  if (element.angle) {
    const r = rotatePoint({ x, y }, center, -element.angle);
    px = r.x;
    py = r.y;
  }
  for (const h of getResizeHandles(element)) {
    if (Math.abs(px - h.x) <= 8 && Math.abs(py - h.y) <= 8) return h.id;
  }
  return null;
}

export interface RenderSceneOptions {
  canvas: HTMLCanvasElement;
  elements: ExcalidrawElement[];
  files: Record<string, AppFile>;
  appState: AppState;
  selectionRect?: { x: number; y: number; width: number; height: number } | null;
  remotePointers?: AppState extends never ? never : import('@/types').RemotePointer[];
}

export function renderScene({
  canvas,
  elements,
  files,
  appState,
  selectionRect,
  remotePointers = [],
}: RenderSceneOptions) {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  const dpr = window.devicePixelRatio || 1;
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  if (canvas.width !== Math.floor(width * dpr) || canvas.height !== Math.floor(height * dpr)) {
    canvas.width = Math.floor(width * dpr);
    canvas.height = Math.floor(height * dpr);
  }

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  ctx.fillStyle = appState.viewBackgroundColor;
  ctx.fillRect(0, 0, width, height);

  if (appState.gridMode) {
    drawGrid(
      ctx,
      width,
      height,
      appState.scrollX,
      appState.scrollY,
      appState.zoom,
      appState.theme === 'dark',
    );
  }

  ctx.save();
  ctx.translate(appState.scrollX * appState.zoom, appState.scrollY * appState.zoom);
  ctx.scale(appState.zoom, appState.zoom);

  const rc = rough.canvas(canvas);
  for (const element of elements) {
    if (!element.isDeleted) {
      renderElement(ctx, rc, element, files);
    }
  }

  drawSelection(ctx, elements, appState.selectedElementIds);

  if (selectionRect) {
    ctx.save();
    ctx.strokeStyle = '#6965db';
    ctx.fillStyle = 'rgba(105,101,219,0.08)';
    ctx.lineWidth = 1 / appState.zoom;
    ctx.fillRect(selectionRect.x, selectionRect.y, selectionRect.width, selectionRect.height);
    ctx.strokeRect(selectionRect.x, selectionRect.y, selectionRect.width, selectionRect.height);
    ctx.restore();
  }

  for (const pointer of remotePointers) {
    ctx.save();
    ctx.fillStyle = pointer.color;
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pointer.x, pointer.y);
    ctx.lineTo(pointer.x + 2, pointer.y + 14);
    ctx.lineTo(pointer.x + 6, pointer.y + 10);
    ctx.lineTo(pointer.x + 12, pointer.y + 16);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.font = '12px Inter, sans-serif';
    const label = pointer.userName;
    const tw = ctx.measureText(label).width;
    ctx.fillStyle = pointer.color;
    ctx.fillRect(pointer.x + 14, pointer.y + 2, tw + 8, 18);
    ctx.fillStyle = '#fff';
    ctx.fillText(label, pointer.x + 18, pointer.y + 15);
    ctx.restore();
  }

  ctx.restore();
}

export function renderElementsToCanvas(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  padding = 40,
): HTMLCanvasElement {
  const visible = elements.filter((e) => !e.isDeleted);
  const bounds = getCommonBounds(visible) ?? { x: 0, y: 0, width: 800, height: 600 };
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(bounds.width + padding * 2);
  canvas.height = Math.ceil(bounds.height + padding * 2);
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.translate(-bounds.x + padding, -bounds.y + padding);
  const rc = rough.canvas(canvas);
  for (const el of visible) {
    renderElement(ctx, rc, el, files);
  }
  return canvas;
}

import type { AppFile, AppState, BoardDocument, ExcalidrawElement } from '@/types';
import { renderElementsToCanvas } from '@/canvas/renderer';
import { getCommonBounds } from './geometry';

export function toBoardDocument(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  appState: AppState,
): BoardDocument {
  return {
    type: 'excalidraw',
    version: 2,
    source: 'excalidraw-clone',
    elements: elements.filter((e) => !e.isDeleted),
    appState: {
      theme: appState.theme,
      viewBackgroundColor: appState.viewBackgroundColor,
      gridMode: appState.gridMode,
      zoom: appState.zoom,
      scrollX: appState.scrollX,
      scrollY: appState.scrollY,
    },
    files,
  };
}

export function downloadJSON(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  appState: AppState,
  filename = 'drawing.excalidraw',
) {
  const doc = toBoardDocument(elements, files, appState);
  const blob = new Blob([JSON.stringify(doc, null, 2)], { type: 'application/json' });
  triggerDownload(blob, filename);
}

export function exportPNG(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  filename = 'drawing.png',
) {
  const canvas = renderElementsToCanvas(elements, files, background);
  canvas.toBlob((blob) => {
    if (blob) triggerDownload(blob, filename);
  }, 'image/png');
}

export function exportSVG(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  filename = 'drawing.svg',
) {
  const visible = elements.filter((e) => !e.isDeleted);
  const bounds = getCommonBounds(visible) ?? { x: 0, y: 0, width: 800, height: 600 };
  const pad = 40;
  const width = bounds.width + pad * 2;
  const height = bounds.height + pad * 2;

  // Rasterize via canvas then embed as image for faithful hand-drawn look
  const canvas = renderElementsToCanvas(elements, files, background, pad);
  const dataUrl = canvas.toDataURL('image/png');
  const svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="100%" height="100%" fill="${background}"/>
  <image width="${width}" height="${height}" xlink:href="${dataUrl}"/>
</svg>`;
  const blob = new Blob([svg], { type: 'image/svg+xml' });
  triggerDownload(blob, filename);
}

export async function importJSONFile(file: File): Promise<BoardDocument> {
  const text = await file.text();
  const data = JSON.parse(text);
  if (!data || !Array.isArray(data.elements)) {
    throw new Error('File JSON không hợp lệ');
  }
  return {
    type: 'excalidraw',
    version: data.version ?? 2,
    source: data.source ?? 'import',
    elements: data.elements,
    appState: data.appState ?? {},
    files: data.files ?? {},
  };
}

function triggerDownload(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export async function fileToDataURL(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

export async function loadImageSize(dataURL: string): Promise<{ width: number; height: number }> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve({ width: img.width, height: img.height });
    img.onerror = reject;
    img.src = dataURL;
  });
}

import { io, Socket } from 'socket.io-client';
import type { ExcalidrawElement, Point } from '@/types';
import { useBoardStore } from '@/store/useBoardStore';

let socket: Socket | null = null;
let userId = `user_${Math.random().toString(36).slice(2, 10)}`;

export function getUserId() {
  return userId;
}

export function connectCollaboration(roomId: string) {
  disconnectCollaboration();

  const { appState, elements, updateAppState, setCollaborators, setRemotePointer, removeRemotePointer, applyRemoteElements } =
    useBoardStore.getState();

  updateAppState({ roomId });

  socket = io('/', {
    path: '/socket.io',
    transports: ['websocket', 'polling'],
  });

  socket.on('connect', () => {
    socket?.emit('join-room', {
      roomId,
      userId,
      userName: appState.userName,
      color: appState.userColor,
      elements,
    });
  });

  socket.on('room-state', (payload: {
    elements: ExcalidrawElement[];
    collaborators: Record<string, { userName: string; color: string }>;
  }) => {
    applyRemoteElements(payload.elements);
    setCollaborators(payload.collaborators);
  });

  socket.on('collaborators', (map: Record<string, { userName: string; color: string }>) => {
    setCollaborators(map);
  });

  socket.on('elements-update', (payload: { elements: ExcalidrawElement[]; from: string }) => {
    if (payload.from === userId) return;
    applyRemoteElements(payload.elements);
  });

  socket.on('pointer-update', (payload: {
    userId: string;
    userName: string;
    color: string;
    x: number;
    y: number;
  }) => {
    if (payload.userId === userId) return;
    setRemotePointer({ ...payload, lastSeen: Date.now() });
  });

  socket.on('user-left', (leftUserId: string) => {
    removeRemotePointer(leftUserId);
  });

  return socket;
}

export function disconnectCollaboration() {
  if (socket) {
    socket.disconnect();
    socket = null;
  }
  useBoardStore.getState().updateAppState({ roomId: null });
  useBoardStore.getState().setCollaborators({});
}

export function broadcastElements(elements: ExcalidrawElement[]) {
  const roomId = useBoardStore.getState().appState.roomId;
  if (!socket || !roomId) return;
  socket.emit('elements-update', { roomId, userId, elements });
}

export function broadcastPointer(point: Point) {
  const { appState } = useBoardStore.getState();
  if (!socket || !appState.roomId) return;
  socket.emit('pointer-update', {
    roomId: appState.roomId,
    userId,
    userName: appState.userName,
    color: appState.userColor,
    x: point.x,
    y: point.y,
  });
}

export function isConnected() {
  return !!socket?.connected;
}

import { useEffect } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import type { ToolType } from '@/types';
import { duplicateElements, getSelectedElements } from '@/utils/elements';

export function useKeyboard() {
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
        return;
      }

      const store = useBoardStore.getState();
      const meta = e.metaKey || e.ctrlKey;
      const key = e.key.toLowerCase();

      if (meta && key === 'z' && !e.shiftKey) {
        e.preventDefault();
        store.undo();
        return;
      }
      if ((meta && key === 'z' && e.shiftKey) || (meta && key === 'y')) {
        e.preventDefault();
        store.redo();
        return;
      }
      if (meta && key === 'd') {
        e.preventDefault();
        store.duplicateSelected();
        return;
      }
      if (meta && key === 'a') {
        e.preventDefault();
        const ids = store.elements.filter((el) => !el.isDeleted).map((el) => el.id);
        store.selectElements(ids);
        return;
      }
      if (meta && key === 'g' && !e.shiftKey) {
        e.preventDefault();
        store.groupSelected();
        return;
      }
      if (meta && key === 'g' && e.shiftKey) {
        e.preventDefault();
        store.ungroupSelected();
        return;
      }
      if (meta && key === 'c') {
        const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
        if (selected.length) {
          e.preventDefault();
          localStorage.setItem('excalidraw-clipboard', JSON.stringify(selected));
        }
        return;
      }
      if (meta && key === 'v') {
        const raw = localStorage.getItem('excalidraw-clipboard');
        if (!raw) return;
        e.preventDefault();
        try {
          const copied = JSON.parse(raw);
          const clones = duplicateElements(copied);
          store.commitHistory();
          store.replaceElements([...store.elements, ...clones]);
          store.selectElements(clones.map((c) => c.id));
        } catch {
          // ignore
        }
        return;
      }
      if (meta && (key === '=' || key === '+')) {
        e.preventDefault();
        store.setZoom(store.appState.zoom * 1.1);
        return;
      }
      if (meta && key === '-') {
        e.preventDefault();
        store.setZoom(store.appState.zoom / 1.1);
        return;
      }
      if (meta && key === '0') {
        e.preventDefault();
        store.setZoom(1);
        store.setScroll(0, 0);
        return;
      }

      if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault();
        store.deleteSelected();
        return;
      }

      if (e.key === 'Escape') {
        store.clearSelection();
        store.setTool('selection');
        return;
      }

      const toolMap: Record<string, ToolType> = {
        v: 'selection',
        h: 'hand',
        r: 'rectangle',
        o: 'ellipse',
        d: 'diamond',
        l: 'line',
        a: 'arrow',
        p: 'freedraw',
        t: 'text',
        e: 'eraser',
      };

      if (!meta && toolMap[key]) {
        store.setTool(toolMap[key]);
        return;
      }

      const step = e.shiftKey ? 10 : 1;
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        store.moveSelected(-step, 0, true);
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        store.moveSelected(step, 0, true);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        store.moveSelected(0, -step, true);
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        store.moveSelected(0, step, true);
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);
}

import { useCallback, useRef } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import {
  boxesIntersect,
  getElementBounds,
  getElementCenter,
  hitTestElement,
  screenToScene,
  snapToGrid,
} from '@/utils/geometry';
import {
  createFreedrawElement,
  createLinearElement,
  createShapeElement,
  createTextElement,
  getSelectedElements,
  normalizeElementSize,
  resizeElement,
  updateLinearFromPoints,
} from '@/utils/elements';
import { hitTestHandle } from '@/canvas/renderer';
import { broadcastElements, broadcastPointer } from '@/services/collaboration';
import type { ExcalidrawElement, Point } from '@/types';

type DragMode =
  | null
  | 'pan'
  | 'draw'
  | 'move'
  | 'resize'
  | 'rotate'
  | 'select-rect'
  | 'erase';

interface InteractionRefs {
  mode: DragMode;
  startScene: Point;
  lastScene: Point;
  drawingId: string | null;
  resizeHandle: string | null;
  spacePressed: boolean;
  didCommit: boolean;
  originElements: ExcalidrawElement[];
}

export function useCanvasInteraction(
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
  setSelectionRect: (rect: { x: number; y: number; width: number; height: number } | null) => void,
) {
  const refs = useRef<InteractionRefs>({
    mode: null,
    startScene: { x: 0, y: 0 },
    lastScene: { x: 0, y: 0 },
    drawingId: null,
    resizeHandle: null,
    spacePressed: false,
    didCommit: false,
    originElements: [],
  });

  const getScenePoint = useCallback(
    (e: { clientX: number; clientY: number }) => {
      const canvas = canvasRef.current;
      if (!canvas) return { x: 0, y: 0 };
      const rect = canvas.getBoundingClientRect();
      const { scrollX, scrollY, zoom, snapToGrid: snap } = useBoardStore.getState().appState;
      const p = screenToScene(e.clientX, e.clientY, scrollX, scrollY, zoom, rect);
      return {
        x: snapToGrid(p.x, snap),
        y: snapToGrid(p.y, snap),
      };
    },
    [canvasRef],
  );

  const findTopElement = useCallback((x: number, y: number) => {
    const elements = useBoardStore.getState().elements;
    for (let i = elements.length - 1; i >= 0; i--) {
      const el = elements[i];
      if (!el.isDeleted && hitTestElement(el, x, y)) return el;
    }
    return null;
  }, []);

  const onPointerDown = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      canvas.setPointerCapture(e.pointerId);

      const store = useBoardStore.getState();
      const tool = store.appState.currentTool;
      const scene = getScenePoint(e);
      const r = refs.current;
      r.startScene = scene;
      r.lastScene = scene;
      r.didCommit = false;
      r.drawingId = null;
      r.resizeHandle = null;
      r.originElements = store.elements.map((el) => structuredClone(el));

      const isPan =
        tool === 'hand' ||
        e.button === 1 ||
        (e.button === 0 && r.spacePressed);

      if (isPan) {
        r.mode = 'pan';
        return;
      }

      if (tool === 'eraser') {
        r.mode = 'erase';
        eraseAt(scene);
        return;
      }

      if (tool === 'selection') {
        const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
        if (selected.length === 1) {
          const handle = hitTestHandle(selected[0], scene.x, scene.y);
          if (handle === 'rotate') {
            r.mode = 'rotate';
            store.commitHistory();
            r.didCommit = true;
            return;
          }
          if (handle) {
            r.mode = 'resize';
            r.resizeHandle = handle;
            store.commitHistory();
            r.didCommit = true;
            return;
          }
        }

        const hit = findTopElement(scene.x, scene.y);
        if (hit) {
          if (!store.appState.selectedElementIds[hit.id]) {
            if (hit.groupIds.length) {
              const groupId = hit.groupIds[hit.groupIds.length - 1];
              const groupEls = store.elements.filter(
                (el) => !el.isDeleted && el.groupIds.includes(groupId),
              );
              store.selectElements(
                groupEls.map((el) => el.id),
                e.shiftKey,
              );
            } else {
              store.selectElements([hit.id], e.shiftKey);
            }
          }
          r.mode = 'move';
          store.commitHistory();
          r.didCommit = true;
          return;
        }

        if (!e.shiftKey) store.clearSelection();
        r.mode = 'select-rect';
        setSelectionRect({ x: scene.x, y: scene.y, width: 0, height: 0 });
        return;
      }

      if (tool === 'text') {
        const text = window.prompt('Nhập nội dung text:', 'Text');
        if (text != null && text !== '') {
          const el = createTextElement(scene.x, scene.y, text, store.appState);
          store.addElement(el);
          broadcastElements(useBoardStore.getState().elements);
        }
        store.setTool('selection');
        return;
      }

      // drawing tools
      store.commitHistory();
      r.didCommit = true;
      r.mode = 'draw';

      let element: ExcalidrawElement | null = null;
      if (tool === 'rectangle' || tool === 'ellipse' || tool === 'diamond') {
        element = createShapeElement(tool, scene.x, scene.y, store.appState);
      } else if (tool === 'line' || tool === 'arrow') {
        element = createLinearElement(tool, scene.x, scene.y, store.appState);
      } else if (tool === 'freedraw') {
        element = createFreedrawElement(scene.x, scene.y, store.appState);
      }

      if (element) {
        r.drawingId = element.id;
        store.addElement(element, false);
      }
    },
    [canvasRef, findTopElement, getScenePoint, setSelectionRect],
  );

  const eraseAt = (scene: Point) => {
    const store = useBoardStore.getState();
    const hit = findTopElement(scene.x, scene.y);
    if (!hit || hit.locked) return;
    if (!refs.current.didCommit) {
      store.commitHistory();
      refs.current.didCommit = true;
    }
    store.updateElement(hit.id, (el) => ({ ...el, isDeleted: true }), false);
    broadcastElements(useBoardStore.getState().elements);
  };

  const onPointerMove = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>) => {
      const store = useBoardStore.getState();
      const scene = getScenePoint(e);
      const r = refs.current;
      broadcastPointer(scene);

      if (!r.mode) {
        r.lastScene = scene;
        return;
      }

      const dx = scene.x - r.lastScene.x;
      const dy = scene.y - r.lastScene.y;

      if (r.mode === 'pan') {
        store.setScroll(
          store.appState.scrollX + (scene.x - r.startScene.x) * 0 + (e.movementX / store.appState.zoom),
          store.appState.scrollY + e.movementY / store.appState.zoom,
        );
        // better pan using movement
        store.setScroll(
          store.appState.scrollX + e.movementX / store.appState.zoom,
          store.appState.scrollY + e.movementY / store.appState.zoom,
        );
        return;
      }

      if (r.mode === 'erase') {
        eraseAt(scene);
        r.lastScene = scene;
        return;
      }

      if (r.mode === 'select-rect') {
        const x = Math.min(r.startScene.x, scene.x);
        const y = Math.min(r.startScene.y, scene.y);
        const width = Math.abs(scene.x - r.startScene.x);
        const height = Math.abs(scene.y - r.startScene.y);
        setSelectionRect({ x, y, width, height });
        r.lastScene = scene;
        return;
      }

      if (r.mode === 'move') {
        store.moveSelected(dx, dy, false);
        r.lastScene = scene;
        return;
      }

      if (r.mode === 'resize' && r.resizeHandle) {
        const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
        if (selected.length === 1) {
          const next = resizeElement(selected[0], r.resizeHandle, dx, dy, e.shiftKey);
          store.updateElement(selected[0].id, () => next, false);
        }
        r.lastScene = scene;
        return;
      }

      if (r.mode === 'rotate') {
        const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
        if (selected.length === 1) {
          const el = selected[0];
          const center = getElementCenter(el);
          const angle = Math.atan2(scene.y - center.y, scene.x - center.x) + Math.PI / 2;
          store.updateElement(el.id, (curr) => ({ ...curr, angle }), false);
        }
        r.lastScene = scene;
        return;
      }

      if (r.mode === 'draw' && r.drawingId) {
        const tool = store.appState.currentTool;
        store.updateElement(
          r.drawingId,
          (el) => {
            if (tool === 'freedraw' && el.type === 'freedraw') {
              const points = [
                ...el.points,
                { x: scene.x - el.x, y: scene.y - el.y },
              ];
              return updateLinearFromPoints({ ...el, points });
            }
            if ((tool === 'line' || tool === 'arrow') && (el.type === 'line' || el.type === 'arrow')) {
              const points = [
                { x: 0, y: 0 },
                { x: scene.x - el.x, y: scene.y - el.y },
              ];
              return updateLinearFromPoints({ ...el, points });
            }
            return normalizeElementSize({
              ...el,
              width: scene.x - el.x,
              height: scene.y - el.y,
            });
          },
          false,
        );
        r.lastScene = scene;
      }
    },
    [getScenePoint, setSelectionRect],
  );

  const onPointerUp = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>) => {
      const store = useBoardStore.getState();
      const r = refs.current;
      const scene = getScenePoint(e);

      if (r.mode === 'select-rect') {
        const box = {
          x: Math.min(r.startScene.x, scene.x),
          y: Math.min(r.startScene.y, scene.y),
          width: Math.abs(scene.x - r.startScene.x),
          height: Math.abs(scene.y - r.startScene.y),
        };
        if (box.width > 2 || box.height > 2) {
          const ids = store.elements
            .filter((el) => !el.isDeleted && boxesIntersect(getElementBounds(el), box))
            .map((el) => el.id);
          store.selectElements(ids, e.shiftKey);
        }
        setSelectionRect(null);
      }

      if (r.mode === 'draw' && r.drawingId) {
        const el = store.elements.find((x) => x.id === r.drawingId);
        if (
          el &&
          el.type !== 'freedraw' &&
          Math.abs(el.width) < 2 &&
          Math.abs(el.height) < 2 &&
          !(el.type === 'line' || el.type === 'arrow')
        ) {
          // tiny accidental shape -> give default size
          store.updateElement(
            el.id,
            (curr) => ({ ...curr, width: 100, height: 80 }),
            false,
          );
        }
        if (store.appState.currentTool !== 'freedraw') {
          store.setTool('selection');
        }
      }

      if (r.mode && r.mode !== 'pan' && r.mode !== 'select-rect') {
        broadcastElements(useBoardStore.getState().elements);
        store.persist();
      }

      r.mode = null;
      r.drawingId = null;
      r.resizeHandle = null;
    },
    [getScenePoint, setSelectionRect],
  );

  const onWheel = useCallback(
    (e: React.WheelEvent<HTMLCanvasElement>) => {
      e.preventDefault();
      const store = useBoardStore.getState();
      if (e.ctrlKey || e.metaKey) {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const { zoom, scrollX, scrollY } = store.appState;
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        const sceneX = mouseX / zoom - scrollX;
        const sceneY = mouseY / zoom - scrollY;
        const factor = e.deltaY > 0 ? 0.9 : 1.1;
        const nextZoom = Math.min(8, Math.max(0.1, zoom * factor));
        store.setZoom(nextZoom);
        store.setScroll(mouseX / nextZoom - sceneX, mouseY / nextZoom - sceneY);
      } else {
        store.setScroll(
          store.appState.scrollX - e.deltaX / store.appState.zoom,
          store.appState.scrollY - e.deltaY / store.appState.zoom,
        );
      }
    },
    [canvasRef],
  );

  const onKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.code === 'Space') refs.current.spacePressed = true;
  }, []);

  const onKeyUp = useCallback((e: KeyboardEvent) => {
    if (e.code === 'Space') refs.current.spacePressed = false;
  }, []);

  return {
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onWheel,
    onKeyDown,
    onKeyUp,
  };
}

import { useRef } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import type { ToolType } from '@/types';
import { Icons } from './icons';
import { createId } from '@/utils/id';
import { createImageElement } from '@/utils/elements';
import { fileToDataURL, loadImageSize } from '@/utils/export';
import { broadcastElements } from '@/services/collaboration';

const tools: { id: ToolType; label: string; icon: keyof typeof Icons; shortcut?: string }[] = [
  { id: 'selection', label: 'Chọn', icon: 'Selection', shortcut: 'V' },
  { id: 'hand', label: 'Di chuyển', icon: 'Hand', shortcut: 'H' },
  { id: 'rectangle', label: 'Hình chữ nhật', icon: 'Rectangle', shortcut: 'R' },
  { id: 'ellipse', label: 'Ellipse', icon: 'Ellipse', shortcut: 'O' },
  { id: 'diamond', label: 'Kim cương', icon: 'Diamond', shortcut: 'D' },
  { id: 'arrow', label: 'Mũi tên', icon: 'Arrow', shortcut: 'A' },
  { id: 'line', label: 'Đường thẳng', icon: 'Line', shortcut: 'L' },
  { id: 'freedraw', label: 'Vẽ tự do', icon: 'Pencil', shortcut: 'P' },
  { id: 'text', label: 'Text', icon: 'Text', shortcut: 'T' },
  { id: 'image', label: 'Ảnh', icon: 'Image' },
  { id: 'eraser', label: 'Tẩy', icon: 'Eraser', shortcut: 'E' },
];

export function Toolbar() {
  const currentTool = useBoardStore((s) => s.appState.currentTool);
  const setTool = useBoardStore((s) => s.setTool);
  const addElement = useBoardStore((s) => s.addElement);
  const addFile = useBoardStore((s) => s.addFile);
  const appState = useBoardStore((s) => s.appState);
  const fileRef = useRef<HTMLInputElement>(null);

  const onToolClick = (tool: ToolType) => {
    if (tool === 'image') {
      fileRef.current?.click();
      return;
    }
    setTool(tool);
  };

  const onImageSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    const dataURL = await fileToDataURL(file);
    const size = await loadImageSize(dataURL);
    const maxW = 480;
    const scale = size.width > maxW ? maxW / size.width : 1;
    const fileId = createId('file');
    addFile({
      id: fileId,
      dataURL,
      mimeType: file.type,
      created: Date.now(),
    });
    const x = -appState.scrollX + 120;
    const y = -appState.scrollY + 120;
    addElement(
      createImageElement(x, y, size.width * scale, size.height * scale, fileId, appState),
    );
    setTool('selection');
    broadcastElements(useBoardStore.getState().elements);
  };

  return (
    <aside className="pointer-events-auto absolute left-4 top-1/2 z-20 -translate-y-1/2">
      <div className="flex flex-col gap-1 rounded-xl bg-white/95 p-1.5 shadow-toolbar backdrop-blur dark:bg-[#2a2a2a]/95">
        {tools.map((tool) => {
          const Icon = Icons[tool.icon];
          const active = currentTool === tool.id;
          return (
            <button
              key={tool.id}
              type="button"
              title={`${tool.label}${tool.shortcut ? ` (${tool.shortcut})` : ''}`}
              onClick={() => onToolClick(tool.id)}
              className={`flex h-10 w-10 items-center justify-center rounded-lg transition ${
                active
                  ? 'bg-accent text-white'
                  : 'text-neutral-700 hover:bg-neutral-100 dark:text-neutral-200 dark:hover:bg-neutral-700'
              }`}
            >
              <Icon />
            </button>
          );
        })}
      </div>
      <input
        ref={fileRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={onImageSelected}
      />
    </aside>
  );
}

import { useBoardStore } from '@/store/useBoardStore';
