export function PropertiesPanel() {
  const elements = useBoardStore((s) => s.elements);
  const appState = useBoardStore((s) => s.appState);
  const updateAppState = useBoardStore((s) => s.updateAppState);
  const updateElements = useBoardStore((s) => s.updateElements);
  const deleteSelected = useBoardStore((s) => s.deleteSelected);
  const duplicateSelected = useBoardStore((s) => s.duplicateSelected);
  const bringToFront = useBoardStore((s) => s.bringToFront);
  const sendToBack = useBoardStore((s) => s.sendToBack);
  const groupSelected = useBoardStore((s) => s.groupSelected);
  const ungroupSelected = useBoardStore((s) => s.ungroupSelected);
  const lockSelected = useBoardStore((s) => s.lockSelected);

  const selected = getSelectedElements(elements, appState.selectedElementIds);
  const hasSelection = selected.length > 0;

  const applyToSelectionOrDefaults = <K extends keyof typeof appState>(
    key: K,
    value: (typeof appState)[K],
    elementKey?: string,
  ) => {
    updateAppState({ [key]: value } as Partial<typeof appState>);
    if (hasSelection && elementKey) {
      updateElements(
        selected.map((e) => e.id),
        (el) => ({ ...el, [elementKey]: value }),
        true,
      );
      broadcastElements(useBoardStore.getState().elements);
    }
  };

  return (
    <aside className="pointer-events-auto absolute right-4 top-20 z-20 w-64 max-h-[calc(100vh-7rem)] overflow-y-auto rounded-xl bg-white/95 p-3 shadow-toolbar backdrop-blur dark:bg-[#2a2a2a]/95">
      <h2 className="mb-3 font-ui text-sm font-semibold text-neutral-800 dark:text-neutral-100">
        {hasSelection ? `Thuộc tính (${selected.length})` : 'Cọ vẽ'}
      </h2>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">Stroke</label>
        <ColorSwatches
          colors={getStrokePalette()}
          value={hasSelection ? selected[0].strokeColor : appState.strokeColor}
          onChange={(c) => applyToSelectionOrDefaults('strokeColor', c, 'strokeColor')}
        />
      </section>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">Background</label>
        <ColorSwatches
          colors={getBgPalette()}
          value={hasSelection ? selected[0].backgroundColor : appState.backgroundColor}
          onChange={(c) => applyToSelectionOrDefaults('backgroundColor', c, 'backgroundColor')}
        />
      </section>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">Fill style</label>
        <div className="flex gap-1">
          {(['hachure', 'cross-hatch', 'solid', 'none'] as FillStyle[]).map((fs) => (
            <button
              key={fs}
              type="button"
              onClick={() => applyToSelectionOrDefaults('fillStyle', fs, 'fillStyle')}
              className={`flex-1 rounded-md px-1 py-1.5 font-ui text-[10px] capitalize ${
                appState.fillStyle === fs
                  ? 'bg-accent text-white'
                  : 'bg-neutral-100 dark:bg-neutral-700'
              }`}
            >
              {fs}
            </button>
          ))}
        </div>
      </section>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">
          Stroke width: {appState.strokeWidth}
        </label>
        <input
          type="range"
          min={1}
          max={8}
          value={appState.strokeWidth}
          onChange={(e) =>
            applyToSelectionOrDefaults('strokeWidth', Number(e.target.value), 'strokeWidth')
          }
          className="w-full"
        />
      </section>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">Stroke style</label>
        <div className="flex gap-1">
          {(['solid', 'dashed', 'dotted'] as StrokeStyle[]).map((ss) => (
            <button
              key={ss}
              type="button"
              onClick={() => applyToSelectionOrDefaults('strokeStyle', ss, 'strokeStyle')}
              className={`flex-1 rounded-md px-1 py-1.5 font-ui text-[10px] capitalize ${
                appState.strokeStyle === ss
                  ? 'bg-accent text-white'
                  : 'bg-neutral-100 dark:bg-neutral-700'
              }`}
            >
              {ss}
            </button>
          ))}
        </div>
      </section>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">
          Roughness: {appState.roughness.toFixed(1)}
        </label>
        <input
          type="range"
          min={0}
          max={2}
          step={0.1}
          value={appState.roughness}
          onChange={(e) =>
            applyToSelectionOrDefaults('roughness', Number(e.target.value), 'roughness')
          }
          className="w-full"
        />
      </section>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">Opacity: {appState.opacity}%</label>
        <input
          type="range"
          min={10}
          max={100}
          value={appState.opacity}
          onChange={(e) =>
            applyToSelectionOrDefaults('opacity', Number(e.target.value), 'opacity')
          }
          className="w-full"
        />
      </section>

      <section className="mb-4 space-y-2">
        <label className="font-ui text-xs text-neutral-500">Font size: {appState.fontSize}</label>
        <input
          type="range"
          min={16}
          max={72}
          value={appState.fontSize}
          onChange={(e) =>
            applyToSelectionOrDefaults('fontSize', Number(e.target.value), 'fontSize')
          }
          className="w-full"
        />
      </section>

      {hasSelection && (
        <section className="grid grid-cols-4 gap-1 border-t border-neutral-200 pt-3 dark:border-neutral-700">
          <IconBtn title="Duplicate" onClick={duplicateSelected}>
            <Icons.Duplicate />
          </IconBtn>
          <IconBtn title="Delete" onClick={deleteSelected}>
            <Icons.Trash />
          </IconBtn>
          <IconBtn title="Bring front" onClick={bringToFront}>
            <Icons.LayersFront />
          </IconBtn>
          <IconBtn title="Send back" onClick={sendToBack}>
            <Icons.LayersBack />
          </IconBtn>
          <IconBtn title="Group" onClick={groupSelected}>
            <span className="font-ui text-xs font-bold">G</span>
          </IconBtn>
          <IconBtn title="Ungroup" onClick={ungroupSelected}>
            <span className="font-ui text-xs font-bold">UG</span>
          </IconBtn>
          <IconBtn title="Lock" onClick={() => lockSelected(true)}>
            <Icons.Lock />
          </IconBtn>
          <IconBtn title="Unlock" onClick={() => lockSelected(false)}>
            <Icons.Unlock />
          </IconBtn>
        </section>
      )}
    </aside>
  );
}

function IconBtn({
  children,
  onClick,
  title,
}: {
  children: React.ReactNode;
  onClick: () => void;
  title: string;
}) {
  return (
    <button
      type="button"
      title={title}
      onClick={() => {
        onClick();
        broadcastElements(useBoardStore.getState().elements);
