            <div className="font-ui text-sm font-semibold leading-tight text-neutral-900 dark:text-white">
              Excalidraw Clone
            </div>
            <div className="font-ui text-[10px] text-neutral-500">Infinite whiteboard</div>
          </div>
        </div>

        <div className="relative flex items-center gap-1 rounded-xl bg-white/95 p-1 shadow-toolbar backdrop-blur dark:bg-[#2a2a2a]/95">
          <TopBtn title="Menu" onClick={() => setMenuOpen((v) => !v)}>
