              <MenuItem
                onClick={() => {
                  persist();
                  setMenuOpen(false);
                }}
              >
                Lưu (LocalStorage)
              </MenuItem>
              <MenuItem
                onClick={() => {
                  downloadJSON(elements, files, appState);
                  setMenuOpen(false);
                }}
              >
                Export JSON
              </MenuItem>
              <MenuItem
                onClick={() => {
                  exportPNG(elements, files, appState.viewBackgroundColor);
                  setMenuOpen(false);
                }}
              >
                Export PNG
              </MenuItem>
              <MenuItem
                onClick={() => {
                  exportSVG(elements, files, appState.viewBackgroundColor);
                  setMenuOpen(false);
                }}
              >
                Export SVG
              </MenuItem>
              <MenuItem
                onClick={() => {
                  importRef.current?.click();
                  setMenuOpen(false);
                }}
              >
                Import JSON
              </MenuItem>
              <MenuItem
                onClick={() => {
                  useBoardStore.getState().loadBoard({ elements: [], files: {} });
                  setMenuOpen(false);
                }}
              >
                Board mới
              </MenuItem>
            </div>
          )}
          <TopBtn title="Undo (Ctrl+Z)" onClick={undo}>
            <Icons.Undo />
          </TopBtn>
          <TopBtn title="Redo (Ctrl+Shift+Z)" onClick={redo}>
            <Icons.Redo />
