        <div className="flex items-center gap-1 rounded-xl bg-white/95 p-1 shadow-toolbar backdrop-blur dark:bg-[#2a2a2a]/95">
          <TopBtn title="Zoom out" onClick={() => setZoom(appState.zoom / 1.1)}>
            <Icons.ZoomOut />
          </TopBtn>
          <button
            type="button"
            className="min-w-[64px] rounded-md px-2 py-1.5 font-ui text-xs font-medium hover:bg-neutral-100 dark:hover:bg-neutral-700"
            onClick={() => {
