            <Icons.Grid />
          </TopBtn>
          <TopBtn
            title="Snap to grid"
            active={appState.snapToGrid}
            onClick={() => updateAppState({ snapToGrid: !appState.snapToGrid })}
          >
            <span className="font-ui text-[10px] font-bold">Snap</span>
