import { getCommonBounds } from '@/utils/geometry';

export function Minimap() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const elements = useBoardStore((s) => s.elements);
  const appState = useBoardStore((s) => s.appState);
  const show = appState.showMinimap;

  useEffect(() => {
    if (!show) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = appState.theme === 'dark' ? '#1a1a1a' : '#f1f3f5';
    ctx.fillRect(0, 0, w, h);

    const visible = elements.filter((e) => !e.isDeleted);
    const bounds = getCommonBounds(visible) ?? { x: -400, y: -300, width: 800, height: 600 };
    const pad = 80;
    const world = {
      x: bounds.x - pad,
      y: bounds.y - pad,
      width: bounds.width + pad * 2,
      height: bounds.height + pad * 2,
    };
    const scale = Math.min(w / world.width, h / world.height);

    ctx.save();
    ctx.translate(
      (w - world.width * scale) / 2,
      (h - world.height * scale) / 2,
    );
    ctx.scale(scale, scale);
    ctx.translate(-world.x, -world.y);

    for (const el of visible) {
      ctx.fillStyle = el.strokeColor || '#6965db';
      ctx.globalAlpha = 0.75;
      ctx.fillRect(el.x, el.y, Math.max(4, Math.abs(el.width)), Math.max(4, Math.abs(el.height)));
    }

    // viewport
    const vw = window.innerWidth / appState.zoom;
    const vh = window.innerHeight / appState.zoom;
    const vx = -appState.scrollX;
    const vy = -appState.scrollY;
    ctx.globalAlpha = 1;
    ctx.strokeStyle = '#6965db';
    ctx.lineWidth = 2 / scale;
    ctx.strokeRect(vx, vy, vw, vh);
    ctx.restore();
  }, [elements, appState, show]);

  if (!show) return null;

  return (
    <div className="pointer-events-auto absolute bottom-4 right-4 z-20 overflow-hidden rounded-xl border border-neutral-200 bg-white/90 shadow-toolbar dark:border-neutral-700 dark:bg-[#2a2a2a]/90">
      <canvas ref={canvasRef} width={180} height={120} className="block" />
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { renderScene } from '@/canvas/renderer';
import { useCanvasInteraction } from '@/hooks/useCanvasInteraction';

export function CanvasBoard() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [selectionRect, setSelectionRect] = useState<{
    x: number;
    y: number;
    width: number;
    height: number;
  } | null>(null);

  const elements = useBoardStore((s) => s.elements);
  const files = useBoardStore((s) => s.files);
  const appState = useBoardStore((s) => s.appState);
  const remotePointers = useBoardStore((s) => s.remotePointers);

  const { onPointerDown, onPointerMove, onPointerUp, onWheel, onKeyDown, onKeyUp } =
    useCanvasInteraction(canvasRef, setSelectionRect);

  useEffect(() => {
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    };
  }, [onKeyDown, onKeyUp]);

  useEffect(() => {
    let raf = 0;
    const draw = () => {
      const canvas = canvasRef.current;
      if (canvas) {
        renderScene({
          canvas,
          elements,
          files,
          appState,
          selectionRect,
          remotePointers: Object.values(remotePointers),
        });
      }
      raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf);
  }, [elements, files, appState, selectionRect, remotePointers]);

  const cursor =
    appState.currentTool === 'hand'
      ? 'grab'
      : appState.currentTool === 'eraser'
        ? 'cell'
        : appState.currentTool === 'text'
          ? 'text'
          : appState.currentTool === 'selection'
            ? 'default'
            : 'crosshair';

  return (
    <canvas
      ref={canvasRef}
      className="absolute inset-0 h-full w-full touch-none"
      style={{ cursor }}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerLeave={onPointerUp}
      onWheel={onWheel}
      onContextMenu={(e) => e.preventDefault()}
    />
  );
}

