import express from 'express';
import { createServer } from 'http';
import { Server } from 'socket.io';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DATA_DIR = path.join(__dirname, 'data');
const BOARDS_FILE = path.join(DATA_DIR, 'boards.json');

interface BoardRecord {
  roomId: string;
  elements: unknown[];
  updatedAt: number;
  history: { elements: unknown[]; at: number }[];
}

interface CollabUser {
  userId: string;
  userName: string;
  color: string;
  socketId: string;
}

type RoomState = {
  elements: unknown[];
  users: Map<string, CollabUser>;
};

const rooms = new Map<string, RoomState>();

function ensureDataDir() {
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
  if (!fs.existsSync(BOARDS_FILE)) fs.writeFileSync(BOARDS_FILE, '{}', 'utf-8');
}

function loadBoards(): Record<string, BoardRecord> {
  ensureDataDir();
  try {
    return JSON.parse(fs.readFileSync(BOARDS_FILE, 'utf-8'));
  } catch {
    return {};
  }
}

function saveBoards(boards: Record<string, BoardRecord>) {
  ensureDataDir();
  fs.writeFileSync(BOARDS_FILE, JSON.stringify(boards, null, 2), 'utf-8');
}

function persistRoom(roomId: string, elements: unknown[]) {
  const boards = loadBoards();
  const prev = boards[roomId];
  const history = prev?.history ?? [];
  history.push({ elements, at: Date.now() });
  if (history.length > 50) history.shift();
  boards[roomId] = {
    roomId,
    elements,
    updatedAt: Date.now(),
    history,
  };
  saveBoards(boards);
}

function getOrCreateRoom(roomId: string): RoomState {
  let room = rooms.get(roomId);
  if (!room) {
    const boards = loadBoards();
    room = {
      elements: boards[roomId]?.elements ?? [],
      users: new Map(),
    };
    rooms.set(roomId, room);
  }
  return room;
}

function collaboratorsMap(room: RoomState) {
  const map: Record<string, { userName: string; color: string }> = {};
  for (const user of room.users.values()) {
    map[user.userId] = { userName: user.userName, color: user.color };
  }
  return map;
}

const app = express();
app.use(cors());
app.use(express.json({ limit: '10mb' }));

app.get('/api/health', (_req, res) => {
  res.json({ ok: true, service: 'excalidraw-clone-server' });
});

app.get('/api/boards/:roomId', (req, res) => {
  const boards = loadBoards();
  const board = boards[req.params.roomId];
  if (!board) {
    res.status(404).json({ error: 'Board not found' });
    return;
  }
  res.json(board);
});

app.post('/api/boards/:roomId', (req, res) => {
  const elements = req.body?.elements ?? [];
  persistRoom(req.params.roomId, elements);
  const room = getOrCreateRoom(req.params.roomId);
  room.elements = elements;
  res.json({ ok: true });
});

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: '*', methods: ['GET', 'POST'] },
  path: '/socket.io',
});

io.on('connection', (socket) => {
  let joinedRoom: string | null = null;
  let joinedUserId: string | null = null;

  socket.on(
    'join-room',
    (payload: {
      roomId: string;
      userId: string;
      userName: string;
      color: string;
      elements?: unknown[];
    }) => {
      const { roomId, userId, userName, color, elements } = payload;
      const room = getOrCreateRoom(roomId);

      if ((!room.elements || room.elements.length === 0) && elements?.length) {
        room.elements = elements;
      }

      joinedRoom = roomId;
      joinedUserId = userId;
      socket.join(roomId);

      room.users.set(userId, { userId, userName, color, socketId: socket.id });

      socket.emit('room-state', {
        elements: room.elements,
        collaborators: collaboratorsMap(room),
      });
      io.to(roomId).emit('collaborators', collaboratorsMap(room));
    },
  );

  socket.on(
    'elements-update',
    (payload: { roomId: string; userId: string; elements: unknown[] }) => {
      const room = getOrCreateRoom(payload.roomId);
      // Last-write-wins with version-friendly full-document sync.
      // Clients send full element arrays; server broadcasts to peers.
      room.elements = payload.elements;
      persistRoom(payload.roomId, payload.elements);
      socket.to(payload.roomId).emit('elements-update', {
        elements: payload.elements,
        from: payload.userId,
      });
    },
  );

  socket.on(
    'pointer-update',
    (payload: {
      roomId: string;
      userId: string;
      userName: string;
      color: string;
      x: number;
      y: number;
    }) => {
      socket.to(payload.roomId).emit('pointer-update', payload);
    },
  );

  socket.on('disconnect', () => {
    if (!joinedRoom || !joinedUserId) return;
    const room = rooms.get(joinedRoom);
    if (!room) return;
    room.users.delete(joinedUserId);
    io.to(joinedRoom).emit('collaborators', collaboratorsMap(room));
    io.to(joinedRoom).emit('user-left', joinedUserId);
    if (room.users.size === 0) {
      // keep elements persisted; drop memory room later if needed
    }
  });
});

const PORT = Number(process.env.PORT || 3001);
httpServer.listen(PORT, () => {
  ensureDataDir();
  console.log(`[server] listening on http://localhost:${PORT}`);
});

