import { useEffect, useRef, useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { renderScene } from '@/canvas/renderer';
import { useCanvasInteraction } from '@/hooks/useCanvasInteraction';

export function CanvasBoard() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const selectionRectRef = useRef<{
    x: number;
    y: number;
    width: number;
    height: number;
  } | null>(null);
  const [selectionRect, setSelectionRectState] = useState<{
    x: number;
    y: number;
    width: number;
    height: number;
  } | null>(null);

  const setSelectionRect = (
    rect: { x: number; y: number; width: number; height: number } | null,
  ) => {
    selectionRectRef.current = rect;
    setSelectionRectState(rect);
  };

  const currentTool = useBoardStore((s) => s.appState.currentTool);

  const { onPointerDown, onPointerMove, onPointerUp, onWheel, onKeyDown, onKeyUp } =
    useCanvasInteraction(canvasRef, setSelectionRect);

  useEffect(() => {
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    };
  }, [onKeyDown, onKeyUp]);

  useEffect(() => {
    let raf = 0;
    const draw = () => {
      const canvas = canvasRef.current;
      if (canvas) {
        const state = useBoardStore.getState();
        renderScene({
          canvas,
          elements: state.elements,
          files: state.files,
          appState: state.appState,
          selectionRect: selectionRectRef.current,
          remotePointers: Object.values(state.remotePointers),
        });
      }
      raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf);
  }, []);

  const cursor =
    currentTool === 'hand'
      ? 'grab'
      : currentTool === 'eraser'
        ? 'cell'
        : currentTool === 'text'
          ? 'text'
          : currentTool === 'selection'
            ? 'default'
            : 'crosshair';

  return (
    <canvas
      ref={canvasRef}
      className="absolute inset-0 h-full w-full touch-none"
      style={{ cursor }}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerLeave={onPointerUp}
      onDoubleClick={(e) => {
        const store = useBoardStore.getState();
        if (store.appState.currentTool !== 'selection') return;
        const canvas = canvasRef.current;
        if (!canvas) return;
        // reuse hit-test via interaction scene conversion
        const rect = canvas.getBoundingClientRect();
        const { scrollX, scrollY, zoom } = store.appState;
        const x = (e.clientX - rect.left) / zoom - scrollX;
        const y = (e.clientY - rect.top) / zoom - scrollY;
        for (let i = store.elements.length - 1; i >= 0; i--) {
          const el = store.elements[i];
          if (el.isDeleted || el.type !== 'text') continue;
          if (
            x >= el.x &&
            x <= el.x + el.width &&
            y >= el.y &&
            y <= el.y + el.height
          ) {
            const next = window.prompt('Sửa text:', el.text);
            if (next != null) {
              store.updateElement(
                el.id,
                (curr) =>
                  curr.type === 'text'
                    ? { ...curr, text: next, width: Math.max(curr.width, next.length * curr.fontSize * 0.5) }
                    : curr,
                true,
              );
            }
            break;
          }
        }
      }}
      onWheel={onWheel}
      onContextMenu={(e) => e.preventDefault()}
    />
  );
}

