import { useBoardStore } from '@/store/useBoardStore';
import { createId } from '@/utils/id';
import { createImageElement } from '@/utils/elements';
import { fileToDataURL, loadImageSize } from '@/utils/export';
import { broadcastElements } from '@/services/collaboration';

export async function insertImageFromFile(
  file: File | Blob,
  sceneX?: number,
  sceneY?: number,
  mimeType?: string,
) {
  const store = useBoardStore.getState();
  const type = mimeType || (file instanceof File ? file.type : 'image/png');
  if (!type.startsWith('image/')) return null;

  const dataURL = await fileToDataURL(file as File);
  const size = await loadImageSize(dataURL);
  const maxW = 480;
  const scale = size.width > maxW ? maxW / size.width : 1;
  const fileId = createId('file');

  store.addFile({
    id: fileId,
    dataURL,
    mimeType: type,
    created: Date.now(),
  });

  const { scrollX, scrollY } = store.appState;
  const x = sceneX ?? -scrollX + 120;
  const y = sceneY ?? -scrollY + 120;

  const element = createImageElement(
    x,
    y,
    size.width * scale,
    size.height * scale,
    fileId,
    store.appState,
  );
  store.addElement(element);
  store.setTool('selection');
  broadcastElements(useBoardStore.getState().elements);
  return element;
}

export function isImageClipboardItem(item: DataTransferItem): boolean {
  return item.kind === 'file' && item.type.startsWith('image/');
}

import { useEffect } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { duplicateElements } from '@/utils/elements';
import { insertImageFromFile, isImageClipboardItem } from '@/utils/imageInsert';
import { broadcastElements } from '@/services/collaboration';

function isEditingTextField(target: EventTarget | null): boolean {
  const el = target as HTMLElement | null;
  if (!el) return false;
  return el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable;
}

export function useClipboardPaste() {
  useEffect(() => {
    const onPaste = async (e: ClipboardEvent) => {
      if (isEditingTextField(e.target)) return;

      const items = e.clipboardData?.items;
      if (items) {
        for (const item of Array.from(items)) {
          if (isImageClipboardItem(item)) {
            e.preventDefault();
            const file = item.getAsFile();
            if (file) await insertImageFromFile(file);
            return;
          }
        }

        // Một số trình duyệt đưa ảnh vào files
        const files = e.clipboardData?.files;
        if (files?.length) {
          for (const file of Array.from(files)) {
            if (file.type.startsWith('image/')) {
              e.preventDefault();
              await insertImageFromFile(file);
              return;
            }
          }
        }
      }

      // Fallback: dán object đã copy trong app
      const raw = localStorage.getItem('excalidraw-clipboard');
      if (!raw) return;
      e.preventDefault();
      try {
        const store = useBoardStore.getState();
        const copied = JSON.parse(raw);
        const clones = duplicateElements(copied);
        store.commitHistory();
        store.replaceElements([...store.elements, ...clones]);
        store.selectElements(clones.map((c) => c.id));
        broadcastElements(useBoardStore.getState().elements);
      } catch {
        // ignore
      }
    };

    const onDrop = async (e: DragEvent) => {
      if (isEditingTextField(e.target)) return;
      const files = e.dataTransfer?.files;
      if (!files?.length) return;

      const images = Array.from(files).filter((f) => f.type.startsWith('image/'));
      if (!images.length) return;

      e.preventDefault();
      const store = useBoardStore.getState();
      const canvas = document.querySelector('canvas');
      let sceneX: number | undefined;
      let sceneY: number | undefined;
      if (canvas) {
        const rect = canvas.getBoundingClientRect();
        const { scrollX, scrollY, zoom } = store.appState;
        sceneX = (e.clientX - rect.left) / zoom - scrollX;
        sceneY = (e.clientY - rect.top) / zoom - scrollY;
      }

      for (let i = 0; i < images.length; i++) {
        await insertImageFromFile(
          images[i],
          sceneX !== undefined ? sceneX + i * 24 : undefined,
          sceneY !== undefined ? sceneY + i * 24 : undefined,
        );
      }
    };

    const onDragOver = (e: DragEvent) => {
      if (e.dataTransfer?.types?.includes('Files')) {
        e.preventDefault();
      }
    };

    window.addEventListener('paste', onPaste);
