import { useEffect, useLayoutEffect, useRef } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { measureText } from '@/utils/elements';
import { broadcastElements } from '@/services/collaboration';
import type { TextElement } from '@/types';

export function TextEditor() {
  const editingTextId = useBoardStore((s) => s.appState.editingTextId);
  const element = useBoardStore((s) =>
    s.elements.find((el): el is TextElement => el.id === editingTextId && el.type === 'text'),
  );
  const zoom = useBoardStore((s) => s.appState.zoom);
  const scrollX = useBoardStore((s) => s.appState.scrollX);
  const scrollY = useBoardStore((s) => s.appState.scrollY);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useLayoutEffect(() => {
    if (!element || !textareaRef.current) return;
    const ta = textareaRef.current;
    ta.focus();
    const len = ta.value.length;
    ta.setSelectionRange(len, len);
    autoResize(ta);
  }, [element?.id]);

  useEffect(() => {
    if (!editingTextId) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        commitAndClose();
      }
    };
    window.addEventListener('keydown', onKeyDown, true);
    return () => window.removeEventListener('keydown', onKeyDown, true);
  }, [editingTextId]);

  if (!element) return null;

  const left = (element.x + scrollX) * zoom;
  const top = (element.y + scrollY) * zoom;

  const commitAndClose = () => {
    const store = useBoardStore.getState();
    const id = store.appState.editingTextId;
    if (!id) return;
    const el = store.elements.find((e) => e.id === id);
    if (el && el.type === 'text') {
      const text = el.text.trim();
      if (!text) {
        store.updateElement(id, (curr) => ({ ...curr, isDeleted: true }), false);
      } else {
        const size = measureText(el.text, el.fontSize, el.fontFamily);
        store.updateElement(
          id,
          (curr) =>
            curr.type === 'text'
              ? { ...curr, width: size.width, height: size.height }
              : curr,
          false,
        );
      }
      broadcastElements(useBoardStore.getState().elements);
      store.persist();
    }
    store.updateAppState({ editingTextId: null });
    store.setTool('selection');
  };

  const onChange = (value: string) => {
    const store = useBoardStore.getState();
    store.updateElement(
      element.id,
      (curr) => {
        if (curr.type !== 'text') return curr;
        const size = measureText(value || ' ', curr.fontSize, curr.fontFamily);
        return { ...curr, text: value, width: size.width, height: size.height };
      },
      false,
    );
    if (textareaRef.current) autoResize(textareaRef.current);
  };

  return (
    <textarea
      ref={textareaRef}
      value={element.text}
      onChange={(e) => onChange(e.target.value)}
      onBlur={commitAndClose}
      onPointerDown={(e) => e.stopPropagation()}
      onKeyDown={(e) => {
        // Cho phép Enter xuống dòng; Escape đã xử lý ở window
        e.stopPropagation();
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          commitAndClose();
        }
      }}
      spellCheck={false}
      className="absolute z-40 m-0 resize-none overflow-hidden border-none bg-transparent p-0 outline-none"
      style={{
        left,
        top,
        width: Math.max(40, element.width) * zoom,
        minHeight: Math.max(element.fontSize * 1.35, element.height) * zoom,
        fontSize: element.fontSize * zoom,
        lineHeight: 1.35,
        fontFamily: element.fontFamily,
        color: element.strokeColor,
        opacity: element.opacity / 100,
        transform: element.angle ? `rotate(${element.angle}rad)` : undefined,
        transformOrigin: 'top left',
        caretColor: element.strokeColor,
        whiteSpace: 'pre',
      }}
    />
  );
}

function autoResize(ta: HTMLTextAreaElement) {
  ta.style.height = 'auto';
