import { useEffect, useRef } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { renderScene } from '@/canvas/renderer';
import { useCanvasInteraction } from '@/hooks/useCanvasInteraction';
import { TextEditor } from '@/components/TextEditor';
import { hitTestElement } from '@/utils/geometry';

export function CanvasBoard() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const selectionRectRef = useRef<{
    x: number;
    y: number;
    width: number;
    height: number;
  } | null>(null);

  const setSelectionRect = (
    rect: { x: number; y: number; width: number; height: number } | null,
  ) => {
    selectionRectRef.current = rect;
  };

  const currentTool = useBoardStore((s) => s.appState.currentTool);
  const editingTextId = useBoardStore((s) => s.appState.editingTextId);

  const { onPointerDown, onPointerMove, onPointerUp, onWheel, onKeyDown, onKeyUp } =
    useCanvasInteraction(canvasRef, setSelectionRect);

  useEffect(() => {
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    };
  }, [onKeyDown, onKeyUp]);

  useEffect(() => {
    let raf = 0;
    const draw = () => {
      const canvas = canvasRef.current;
      if (canvas) {
        const state = useBoardStore.getState();
        renderScene({
          canvas,
          elements: state.elements,
          files: state.files,
          appState: state.appState,
          selectionRect: selectionRectRef.current,
          remotePointers: Object.values(state.remotePointers),
        });
      }
      raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf);
  }, []);

  const cursor =
    currentTool === 'hand'
      ? 'grab'
      : currentTool === 'eraser'
        ? 'cell'
        : currentTool === 'text'
          ? 'text'
          : currentTool === 'selection'
            ? 'default'
            : 'crosshair';

  const startEditTextAt = (clientX: number, clientY: number) => {
    const store = useBoardStore.getState();
    if (store.appState.editingTextId) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const { scrollX, scrollY, zoom } = store.appState;
    const x = (clientX - rect.left) / zoom - scrollX;
    const y = (clientY - rect.top) / zoom - scrollY;

    for (let i = store.elements.length - 1; i >= 0; i--) {
      const el = store.elements[i];
      if (el.isDeleted || el.type !== 'text' || el.locked) continue;
      if (hitTestElement(el, x, y)) {
        store.commitHistory();
        store.selectElements([el.id]);
        store.updateAppState({ editingTextId: el.id });
        return;
      }
    }
  };

  return (
    <div className="absolute inset-0">
      <canvas
        ref={canvasRef}
        className="absolute inset-0 h-full w-full touch-none"
        style={{ cursor: editingTextId ? 'default' : cursor }}
        onPointerDown={editingTextId ? undefined : onPointerDown}
        onPointerMove={editingTextId ? undefined : onPointerMove}
        onPointerUp={editingTextId ? undefined : onPointerUp}
        onPointerLeave={editingTextId ? undefined : onPointerUp}
        onDoubleClick={(e) => {
          if (useBoardStore.getState().appState.currentTool === 'selection') {
            startEditTextAt(e.clientX, e.clientY);
          }
        }}
        onWheel={onWheel}
        onContextMenu={(e) => e.preventDefault()}
      />
      <TextEditor />
    </div>
  );
}

