export function renderElementsToCanvas(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  padding = 40,
): HTMLCanvasElement {
  const visible = elements.filter((e) => !e.isDeleted);
  const bounds = getCommonBounds(visible) ?? { x: 0, y: 0, width: 800, height: 600 };
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(bounds.width + padding * 2);
  canvas.height = Math.ceil(bounds.height + padding * 2);
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.translate(-bounds.x + padding, -bounds.y + padding);
  const rc = rough.canvas(canvas);
  for (const el of visible) {
    renderElement(ctx, rc, el, files);
  }
  return canvas;
}

input.new_string:
export function renderElementsToCanvas(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  padding = 40,
): HTMLCanvasElement {
  const visible = elements.filter((e) => !e.isDeleted);
  const bounds = getCommonBounds(visible) ?? { x: 0, y: 0, width: 800, height: 600 };
  return renderRegionToCanvas(
    visible,
    files,
    background,
    {
      x: bounds.x - padding,
      y: bounds.y - padding,
      width: bounds.width + padding * 2,
      height: bounds.height + padding * 2,
    },
  );
}

/** Render đúng khung scene (khoanh vùng) ra canvas ảnh */
export function renderRegionToCanvas(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  region: { x: number; y: number; width: number; height: number },
  scale = 1,
): HTMLCanvasElement {
  const visible = elements.filter((e) => !e.isDeleted);
  const width = Math.max(1, Math.ceil(region.width * scale));
  const height = Math.max(1, Math.ceil(region.height * scale));
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);
  ctx.scale(scale, scale);
  ctx.translate(-region.x, -region.y);
  const rc = rough.canvas(canvas);
  for (const el of visible) {
    renderElement(ctx, rc, el, files);
  }
  return canvas;
}

