}

if (appState.captureRegion) {
  const r = appState.captureRegion;
  ctx.save();
  ctx.strokeStyle = '#0ca678';
  ctx.fillStyle = 'rgba(12,166,120,0.08)';
  ctx.lineWidth = 2 / appState.zoom;
  ctx.setLineDash([8 / appState.zoom, 5 / appState.zoom]);
  ctx.fillRect(r.x, r.y, r.width, r.height);
  ctx.strokeRect(r.x, r.y, r.width, r.height);
  ctx.setLineDash([]);
  // góc khung
  const corner = 10 / appState.zoom;
  ctx.lineWidth = 3 / appState.zoom;
  ctx.beginPath();
  // NW
  ctx.moveTo(r.x, r.y + corner);
  ctx.lineTo(r.x, r.y);
  ctx.lineTo(r.x + corner, r.y);
  // NE
  ctx.moveTo(r.x + r.width - corner, r.y);
  ctx.lineTo(r.x + r.width, r.y);
  ctx.lineTo(r.x + r.width, r.y + corner);
  // SW
  ctx.moveTo(r.x, r.y + r.height - corner);
  ctx.lineTo(r.x, r.y + r.height);
  ctx.lineTo(r.x + corner, r.y + r.height);
  // SE
  ctx.moveTo(r.x + r.width - corner, r.y + r.height);
  ctx.lineTo(r.x + r.width, r.y + r.height);
  ctx.lineTo(r.x + r.width, r.y + r.height - corner);
  ctx.stroke();
  ctx.restore();
}

