function canvasToBlob(canvas: HTMLCanvasElement): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error('Không tạo được ảnh PNG'));
    }, 'image/png');
  });
}

/** Xuất khung khoanh vùng thành canvas */
export function regionToCanvas(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  region: BoundBox,
  scale = 2,
) {
  return renderRegionToCanvas(elements, files, background, region, scale);
}

export async function downloadRegionPNG(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  region: BoundBox,
  filename = `region-${Date.now()}.png`,
) {
  const canvas = regionToCanvas(elements, files, background, region);
  const blob = await canvasToBlob(canvas);
  triggerDownload(blob, filename);
}

/** Copy khung vùng vào clipboard hệ thống (ảnh PNG) */
export async function copyRegionToClipboard(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  region: BoundBox,
): Promise<boolean> {
  const canvas = regionToCanvas(elements, files, background, region);
  const blob = await canvasToBlob(canvas);

  if (navigator.clipboard && 'write' in navigator.clipboard && typeof ClipboardItem !== 'undefined') {
    await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
    return true;
  }

  // Fallback: vẫn tải file nếu trình duyệt không cho copy ảnh
  triggerDownload(blob, `region-${Date.now()}.png`);
  return false;
}

