import { useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { copyRegionToClipboard, downloadRegionPNG } from '@/utils/export';
import { Icons } from './icons';

export function RegionCaptureBar() {
  const captureRegion = useBoardStore((s) => s.appState.captureRegion);
  const zoom = useBoardStore((s) => s.appState.zoom);
  const scrollX = useBoardStore((s) => s.appState.scrollX);
  const scrollY = useBoardStore((s) => s.appState.scrollY);
  const updateAppState = useBoardStore((s) => s.updateAppState);
  const setTool = useBoardStore((s) => s.setTool);
  const [status, setStatus] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  if (!captureRegion) return null;

  const left = (captureRegion.x + scrollX) * zoom;
  const top = (captureRegion.y + scrollY) * zoom;
  const width = captureRegion.width * zoom;

  const clear = () => {
    updateAppState({ captureRegion: null });
    setStatus(null);
    setTool('selection');
  };

  const onCopy = async () => {
    const store = useBoardStore.getState();
    if (!store.appState.captureRegion) return;
    setBusy(true);
    setStatus(null);
    try {
      const ok = await copyRegionToClipboard(
        store.elements,
        store.files,
        store.appState.viewBackgroundColor,
        store.appState.captureRegion,
      );
      setStatus(ok ? 'Đã copy ảnh vào clipboard' : 'Đã tải ảnh (trình duyệt không hỗ trợ copy)');
    } catch {
      setStatus('Copy thất bại — thử Lưu PNG');
    } finally {
      setBusy(false);
    }
  };

  const onSave = async () => {
    const store = useBoardStore.getState();
    if (!store.appState.captureRegion) return;
    setBusy(true);
    setStatus(null);
    try {
      await downloadRegionPNG(
        store.elements,
        store.files,
        store.appState.viewBackgroundColor,
        store.appState.captureRegion,
      );
      setStatus('Đã lưu file PNG');
    } catch {
      setStatus('Lưu ảnh thất bại');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      className="pointer-events-auto absolute z-30 flex -translate-x-1/2 flex-col items-center gap-1"
      style={{
        left: left + width / 2,
        top: Math.max(8, top - 52),
      }}
    >
      <div className="flex items-center gap-1 rounded-xl bg-white/95 p-1 shadow-toolbar backdrop-blur dark:bg-[#2a2a2a]/95">
        <button
          type="button"
          disabled={busy}
          onClick={onCopy}
          className="flex items-center gap-1.5 rounded-lg bg-accent px-3 py-1.5 font-ui text-xs font-medium text-white hover:bg-accent-hover disabled:opacity-60"
        >
          <Icons.CopyImage />
          Copy ảnh
        </button>
        <button
          type="button"
          disabled={busy}
          onClick={onSave}
          className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 font-ui text-xs font-medium text-neutral-700 hover:bg-neutral-100 dark:text-neutral-100 dark:hover:bg-neutral-700 disabled:opacity-60"
        >
          <Icons.Download />
          Lưu PNG
        </button>
        <button
          type="button"
          onClick={clear}
          className="rounded-lg px-2 py-1.5 font-ui text-xs text-neutral-500 hover:bg-neutral-100 dark:hover:bg-neutral-700"
        >
          Hủy
        </button>
      </div>
      {status && (
        <div className="rounded-full bg-emerald-600 px-2.5 py-0.5 font-ui text-[10px] text-white shadow">
          {status}
        </div>
      )}
    </div>
  );
}

