import { useEffect, useLayoutEffect, useRef } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { measureText } from '@/utils/elements';
import { broadcastElements } from '@/services/collaboration';
import type { TextElement } from '@/types';

function commitEditingText() {
  const store = useBoardStore.getState();
  const id = store.appState.editingTextId;
  if (!id) return;

  const el = store.elements.find((e) => e.id === id);
  if (el && el.type === 'text') {
    const text = el.text.trim();
    if (!text) {
      store.updateElement(id, (curr) => ({ ...curr, isDeleted: true }), false);
    } else {
      const size = measureText(el.text, el.fontSize, el.fontFamily);
      store.updateElement(
        id,
        (curr) =>
          curr.type === 'text' ? { ...curr, width: size.width, height: size.height } : curr,
        false,
      );
    }
    broadcastElements(useBoardStore.getState().elements);
    store.persist();
  }

  store.updateAppState({ editingTextId: null });
  store.setTool('selection');
}

export function TextEditor() {
  const editingTextId = useBoardStore((s) => s.appState.editingTextId);
  const element = useBoardStore((s) =>
    s.elements.find((el): el is TextElement => el.id === editingTextId && el.type === 'text' && !el.isDeleted),
  );
  const zoom = useBoardStore((s) => s.appState.zoom);
  const scrollX = useBoardStore((s) => s.appState.scrollX);
  const scrollY = useBoardStore((s) => s.appState.scrollY);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const canCommitBlurRef = useRef(false);
  const editingIdRef = useRef<string | null>(null);

  useLayoutEffect(() => {
    if (!element) return;
    editingIdRef.current = element.id;
    canCommitBlurRef.current = false;

    const ta = textareaRef.current;
    if (!ta) return;

    // Đợi pointerup của cú click tạo text xong rồi mới focus,
    // tránh blur ngay lập tức làm mất text rỗng.
    const focusTimer = window.setTimeout(() => {
      ta.focus();
      const len = ta.value.length;
      ta.setSelectionRange(len, len);
      autoResize(ta);
    }, 0);

    const allowTimer = window.setTimeout(() => {
      canCommitBlurRef.current = true;
    }, 200);

    return () => {
      window.clearTimeout(focusTimer);
      window.clearTimeout(allowTimer);
      // Strict Mode unmount: KHÔNG commit/xóa text
    };
  }, [element?.id]);

  useEffect(() => {
    if (!editingTextId) return;
    const onPointerUp = () => {
      // Sau khi nhả chuột tạo text, cho phép commit blur
      window.setTimeout(() => {
        canCommitBlurRef.current = true;
        textareaRef.current?.focus();
      }, 0);
    };
    window.addEventListener('pointerup', onPointerUp, { once: true });
    return () => window.removeEventListener('pointerup', onPointerUp);
  }, [editingTextId]);

  if (!element) return null;

  const left = (element.x + scrollX) * zoom;
  const top = (element.y + scrollY) * zoom;

  return (
    <textarea
      ref={textareaRef}
      value={element.text}
      placeholder="Type here…"
      onChange={(e) => {
        const value = e.target.value;
        useBoardStore.getState().updateElement(
          element.id,
          (curr) => {
            if (curr.type !== 'text') return curr;
            const size = measureText(value || ' ', curr.fontSize, curr.fontFamily);
            return { ...curr, text: value, width: size.width, height: size.height };
          },
          false,
        );
        if (textareaRef.current) autoResize(textareaRef.current);
      }}
      onBlur={() => {
        if (!canCommitBlurRef.current || editingIdRef.current !== element.id) {
          // Blur sớm (do click tạo text) → giữ editor, focus lại
          requestAnimationFrame(() => {
            if (useBoardStore.getState().appState.editingTextId === element.id) {
              textareaRef.current?.focus();
            }
          });
          return;
        }
        commitEditingText();
      }}
      onPointerDown={(e) => e.stopPropagation()}
      onMouseDown={(e) => e.stopPropagation()}
      onKeyDown={(e) => {
        e.stopPropagation();
        if (e.key === 'Escape') {
          e.preventDefault();
          canCommitBlurRef.current = true;
          commitEditingText();
          return;
        }
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          canCommitBlurRef.current = true;
          commitEditingText();
        }
      }}
      spellCheck={false}
      className="absolute z-50 m-0 resize-none overflow-hidden rounded-sm border border-accent/40 bg-white/90 p-0.5 outline-none dark:bg-black/50"
      style={{
        left,
        top,
        minWidth: Math.max(80, element.width) * zoom,
        minHeight: Math.max(element.fontSize * 1.35, element.height) * zoom,
        fontSize: element.fontSize * zoom,
        lineHeight: 1.35,
        fontFamily: element.fontFamily,
        color: element.strokeColor,
        opacity: element.opacity / 100,
        transform: element.angle ? `rotate(${element.angle}rad)` : undefined,
        transformOrigin: 'top left',
        caretColor: element.strokeColor,
        whiteSpace: 'pre-wrap',
      }}
    />
  );
}

function autoResize(ta: HTMLTextAreaElement) {
  ta.style.height = '0px';
  ta.style.height = `${Math.max(ta.scrollHeight, 24)}px`;
  ta.style.width = '0px';
  ta.style.width = `${Math.max(80, ta.scrollWidth + 16)}px`;
}

