import type { BoundBox, ExcalidrawElement } from '@/types';
import { boxesIntersect, getCommonBounds, getElementBounds, getElementCenter } from '@/utils/geometry';
import { bumpVersion, createShapeElement, duplicateElements, getSelectedElements } from '@/utils/elements';
import { useBoardStore } from '@/store/useBoardStore';
import { createId } from '@/utils/id';

const ELEMENT_CLIPBOARD = 'excalidraw-clipboard';
const STYLE_CLIPBOARD = 'excalidraw-style-clipboard';
const LIBRARY_KEY = 'excalidraw-library';

export function getElementsInRegion(
  elements: ExcalidrawElement[],
  region: BoundBox,
): ExcalidrawElement[] {
  return elements.filter(
    (el) => !el.isDeleted && boxesIntersect(getElementBounds(el), region),
  );
}

export function selectElementsInRegion(region: BoundBox) {
  const store = useBoardStore.getState();
  const ids = getElementsInRegion(store.elements, region).map((el) => el.id);
  store.selectElements(ids);
  return ids;
}

export function copySelectedElements() {
  const store = useBoardStore.getState();
  const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
  if (!selected.length) return false;
  localStorage.setItem(ELEMENT_CLIPBOARD, JSON.stringify(selected));
  return true;
}

export function cutSelectedElements() {
  if (!copySelectedElements()) return false;
  useBoardStore.getState().deleteSelected();
  return true;
}

export function pasteElements() {
  const raw = localStorage.getItem(ELEMENT_CLIPBOARD);
  if (!raw) return false;
  try {
    const store = useBoardStore.getState();
    const copied = JSON.parse(raw) as ExcalidrawElement[];
    const clones = duplicateElements(copied);
    store.commitHistory();
    store.replaceElements([...store.elements, ...clones]);
    store.selectElements(clones.map((c) => c.id));
    return true;
  } catch {
    return false;
  }
}

export function copySelectedStyles() {
  const store = useBoardStore.getState();
  const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
  if (!selected.length) return false;
  const el = selected[0];
  localStorage.setItem(
    STYLE_CLIPBOARD,
    JSON.stringify({
      strokeColor: el.strokeColor,
      backgroundColor: el.backgroundColor,
      fillStyle: el.fillStyle,
      strokeWidth: el.strokeWidth,
      strokeStyle: el.strokeStyle,
      roughness: el.roughness,
      opacity: el.opacity,
      fontSize: el.type === 'text' ? el.fontSize : undefined,
      fontFamily: el.type === 'text' ? el.fontFamily : undefined,
    }),
  );
  return true;
}

export function pasteSelectedStyles() {
  const raw = localStorage.getItem(STYLE_CLIPBOARD);
  if (!raw) return false;
  try {
    const style = JSON.parse(raw);
    const store = useBoardStore.getState();
    const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
    if (!selected.length) return false;
    store.updateElements(
      selected.map((e) => e.id),
      (el) => {
        const next = {
          ...el,
          strokeColor: style.strokeColor ?? el.strokeColor,
          backgroundColor: style.backgroundColor ?? el.backgroundColor,
          fillStyle: style.fillStyle ?? el.fillStyle,
          strokeWidth: style.strokeWidth ?? el.strokeWidth,
          strokeStyle: style.strokeStyle ?? el.strokeStyle,
          roughness: style.roughness ?? el.roughness,
          opacity: style.opacity ?? el.opacity,
        };
        if (next.type === 'text') {
          return {
            ...next,
            fontSize: style.fontSize ?? next.fontSize,
            fontFamily: style.fontFamily ?? next.fontFamily,
          };
        }
        return next;
      },
      true,
    );
    return true;
  } catch {
    return false;
  }
}

export function wrapSelectionInFrame() {
  const store = useBoardStore.getState();
  const region = store.appState.captureRegion;
  const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
  const bounds =
    region ??
    getCommonBounds(selected);
  if (!bounds || bounds.width < 4 || bounds.height < 4) return false;

  const pad = 12;
  const frame = createShapeElement(
    'rectangle',
    bounds.x - pad,
    bounds.y - pad,
    store.appState,
  );
  frame.width = bounds.width + pad * 2;
  frame.height = bounds.height + pad * 2;
  frame.backgroundColor = 'transparent';
  frame.fillStyle = 'none';
  frame.strokeColor = '#1971c2';
  frame.strokeWidth = 2;
  frame.roughness = 0;

  store.commitHistory();
  // Frame nằm dưới các object trong vùng
  store.replaceElements([frame, ...store.elements]);
  store.selectElements([frame.id]);
  return true;
}

export function addSelectionToLibrary() {
  const store = useBoardStore.getState();
  const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
  if (!selected.length) return false;
  try {
    const prev = JSON.parse(localStorage.getItem(LIBRARY_KEY) || '[]') as unknown[];
    prev.push({
      id: createId('lib'),
      created: Date.now(),
      elements: selected,
    });
    localStorage.setItem(LIBRARY_KEY, JSON.stringify(prev));
    return true;
  } catch {
    return false;
  }
}

export function flipSelected(axis: 'horizontal' | 'vertical') {
  const store = useBoardStore.getState();
  const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
  if (!selected.length) return false;
  const bounds = getCommonBounds(selected);
  if (!bounds) return false;
  const cx = bounds.x + bounds.width / 2;
  const cy = bounds.y + bounds.height / 2;

  store.updateElements(
    selected.map((e) => e.id),
    (el) => {
      if (el.locked) return el;
      let next = { ...el };
      if (axis === 'horizontal') {
        next.x = cx * 2 - (el.x + el.width);
        next.angle = -el.angle;
        if ('points' in next && next.points) {
          next.points = next.points.map((p) => ({ x: el.width - p.x, y: p.y }));
        }
      } else {
        next.y = cy * 2 - (el.y + el.height);
        next.angle = -el.angle;
        if ('points' in next && next.points) {
          next.points = next.points.map((p) => ({ x: p.x, y: el.height - p.y }));
        }
      }
      return bumpVersion(next);
    },
    true,
  );
  return true;
}

export function bringForward() {
  const store = useBoardStore.getState();
  const { elements, appState } = store;
  const selected = getSelectedElements(elements, appState.selectedElementIds);
  if (!selected.length) return;
  const ids = new Set(selected.map((e) => e.id));
  const next = [...elements];
  for (let i = next.length - 2; i >= 0; i--) {
    if (ids.has(next[i].id) && !ids.has(next[i + 1].id)) {
      const tmp = next[i];
      next[i] = next[i + 1];
      next[i + 1] = bumpVersion(tmp);
    }
  }
  store.commitHistory();
  store.replaceElements(next);
}

export function sendBackward() {
  const store = useBoardStore.getState();
  const { elements, appState } = store;
  const selected = getSelectedElements(elements, appState.selectedElementIds);
  if (!selected.length) return;
  const ids = new Set(selected.map((e) => e.id));
  const next = [...elements];
  for (let i = 1; i < next.length; i++) {
    if (ids.has(next[i].id) && !ids.has(next[i - 1].id)) {
      const tmp = next[i];
      next[i] = next[i - 1];
      next[i - 1] = bumpVersion(tmp);
    }
  }
  store.commitHistory();
  store.replaceElements(next);
}

