/** Copy khung vùng vào clipboard hệ thống (ảnh PNG) */
export async function copyRegionToClipboard(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  region: BoundBox,
): Promise<boolean> {
  const canvas = regionToCanvas(elements, files, background, region);
  const blob = await canvasToBlob(canvas);

  if (navigator.clipboard && 'write' in navigator.clipboard && typeof ClipboardItem !== 'undefined') {
    await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
    return true;
  }

  // Fallback: vẫn tải file nếu trình duyệt không cho copy ảnh
  triggerDownload(blob, `region-${Date.now()}.png`);
  return false;
}

/** Copy khung vùng thành SVG (nhúng PNG) vào clipboard dạng text/svg */
export async function copyRegionAsSVG(
  elements: ExcalidrawElement[],
  files: Record<string, AppFile>,
  background: string,
  region: BoundBox,
): Promise<boolean> {
  const canvas = regionToCanvas(elements, files, background, region, 2);
  const dataUrl = canvas.toDataURL('image/png');
  const width = canvas.width;
  const height = canvas.height;
  const svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="100%" height="100%" fill="${background}"/>
  <image width="${width}" height="${height}" xlink:href="${dataUrl}"/>
</svg>`;

  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(svg);
    return true;
  }
  const blob = new Blob([svg], { type: 'image/svg+xml' });
  triggerDownload(blob, `region-${Date.now()}.svg`);
  return false;
}

export function getCaptureOrSelectionRegion(
  elements: ExcalidrawElement[],
  selectedIds: Record<string, true>,
  captureRegion: BoundBox | null,
): BoundBox | null {
  if (captureRegion) return captureRegion;
  const selected = elements.filter((el) => selectedIds[el.id] && !el.isDeleted);
  return getCommonBounds(selected);
}

