import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import {
  addSelectionToLibrary,
  bringForward,
  copySelectedElements,
  copySelectedStyles,
  cutSelectedElements,
  flipSelected,
  pasteElements,
  pasteSelectedStyles,
  selectElementsInRegion,
  sendBackward,
  wrapSelectionInFrame,
} from '@/utils/selectionActions';
import { copyRegionAsSVG, copyRegionToClipboard, downloadRegionPNG } from '@/utils/export';
import { getCommonBounds } from '@/utils/geometry';
import { getSelectedElements } from '@/utils/elements';
import { broadcastElements } from '@/services/collaboration';

export interface ContextMenuState {
  x: number;
  y: number;
}

interface Props {
  menu: ContextMenuState | null;
  onClose: () => void;
  onToast?: (msg: string) => void;
}

type Item =
  | { type: 'sep' }
  | {
      type: 'item';
      label: string;
      shortcut?: string;
      danger?: boolean;
      disabled?: boolean;
      action: () => void | Promise<void>;
    };

export function ContextMenu({ menu, onClose, onToast }: Props) {
  const ref = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState({ x: 0, y: 0 });

  useLayoutEffect(() => {
    if (!menu || !ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const x = Math.min(menu.x, window.innerWidth - rect.width - 8);
    const y = Math.min(menu.y, window.innerHeight - rect.height - 8);
    setPos({ x: Math.max(8, x), y: Math.max(8, y) });
  }, [menu]);

  useEffect(() => {
    if (!menu) return;
    const close = () => onClose();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('pointerdown', close);
    window.addEventListener('keydown', onKey);
    window.addEventListener('blur', close);
    return () => {
      window.removeEventListener('pointerdown', close);
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('blur', close);
    };
  }, [menu, onClose]);

  if (!menu) return null;

  const store = useBoardStore.getState();
  const captureRegion = store.appState.captureRegion;
  const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
  const hasSelection = selected.length > 0 || !!captureRegion;

  const ensureSelectionFromRegion = () => {
    if (captureRegion) {
      selectElementsInRegion(captureRegion);
    }
  };

  const getRegion = () => {
    const s = useBoardStore.getState();
    if (s.appState.captureRegion) return s.appState.captureRegion;
    return getCommonBounds(
      getSelectedElements(s.elements, s.appState.selectedElementIds),
    );
  };

  const toast = (msg: string) => onToast?.(msg);

  const run = async (fn: () => void | Promise<void>) => {
    try {
      await fn();
      broadcastElements(useBoardStore.getState().elements);
    } finally {
      onClose();
    }
  };

  const items: Item[] = [
    {
      type: 'item',
      label: 'Cut',
      shortcut: 'Ctrl+X',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        cutSelectedElements();
        useBoardStore.getState().updateAppState({ captureRegion: null });
      },
    },
    {
      type: 'item',
      label: 'Copy',
      shortcut: 'Ctrl+C',
      disabled: !hasSelection,
      action: async () => {
        const region = getRegion();
        if (region && captureRegion) {
          const ok = await copyRegionToClipboard(
            store.elements,
            store.files,
            store.appState.viewBackgroundColor,
            region,
          );
          toast(ok ? 'Đã copy ảnh PNG' : 'Đã tải PNG');
          return;
        }
        ensureSelectionFromRegion();
        copySelectedElements();
        toast('Đã copy đối tượng');
      },
    },
    {
      type: 'item',
      label: 'Paste',
      shortcut: 'Ctrl+V',
      action: () => {
        pasteElements();
      },
    },
    { type: 'sep' },
    {
      type: 'item',
      label: 'Wrap selection in frame',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        wrapSelectionInFrame();
        toast('Đã tạo frame');
      },
    },
    { type: 'sep' },
    {
      type: 'item',
      label: 'Copy to clipboard as PNG',
      shortcut: 'Shift+Alt+C',
      disabled: !hasSelection,
      action: async () => {
        const region = getRegion();
        if (!region) return;
        const s = useBoardStore.getState();
        const ok = await copyRegionToClipboard(
          s.elements,
          s.files,
          s.appState.viewBackgroundColor,
          region,
        );
        toast(ok ? 'Đã copy PNG vào clipboard' : 'Đã tải file PNG');
      },
    },
    {
      type: 'item',
      label: 'Copy to clipboard as SVG',
      disabled: !hasSelection,
      action: async () => {
        const region = getRegion();
        if (!region) return;
        const s = useBoardStore.getState();
        const ok = await copyRegionAsSVG(
          s.elements,
          s.files,
          s.appState.viewBackgroundColor,
          region,
        );
        toast(ok ? 'Đã copy SVG vào clipboard' : 'Đã tải file SVG');
      },
    },
    {
      type: 'item',
      label: 'Save region as PNG…',
      disabled: !hasSelection,
      action: async () => {
        const region = getRegion();
        if (!region) return;
        const s = useBoardStore.getState();
        await downloadRegionPNG(
          s.elements,
          s.files,
          s.appState.viewBackgroundColor,
          region,
        );
        toast('Đã lưu PNG');
      },
    },
    { type: 'sep' },
    {
      type: 'item',
      label: 'Copy styles',
      shortcut: 'Ctrl+Alt+C',
