        ensureSelectionFromRegion();
        copySelectedStyles();
        toast('Đã copy styles');
      },
    },
    {
      type: 'item',
      label: 'Paste styles',
      shortcut: 'Ctrl+Alt+V',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        pasteSelectedStyles();
