    { type: 'sep' },
    {
      type: 'item',
      label: 'Group selection',
      shortcut: 'Ctrl+G',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        useBoardStore.getState().groupSelected();
      },
    },
    {
      type: 'item',
      label: 'Add to library',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        if (addSelectionToLibrary()) toast('Đã thêm vào library');
      },
    },
    { type: 'sep' },
    {
      type: 'item',
      label: 'Send backward',
      shortcut: 'Ctrl+[',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        sendBackward();
      },
    },
    {
      type: 'item',
      label: 'Bring forward',
      shortcut: 'Ctrl+]',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        bringForward();
      },
    },
    {
      type: 'item',
      label: 'Send to back',
      shortcut: 'Ctrl+Shift+[',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        useBoardStore.getState().sendToBack();
      },
    },
    {
      type: 'item',
      label: 'Bring to front',
      shortcut: 'Ctrl+Shift+]',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        useBoardStore.getState().bringToFront();
      },
    },
    { type: 'sep' },
    {
      type: 'item',
      label: 'Flip horizontal',
      shortcut: 'Shift+H',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        flipSelected('horizontal');
      },
    },
    {
      type: 'item',
      label: 'Flip vertical',
      shortcut: 'Shift+V',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        flipSelected('vertical');
      },
    },
    { type: 'sep' },
    {
      type: 'item',
      label: 'Duplicate',
      shortcut: 'Ctrl+D',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        useBoardStore.getState().duplicateSelected();
      },
    },
    {
      type: 'item',
      label: 'Lock',
      shortcut: 'Ctrl+Shift+L',
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        useBoardStore.getState().lockSelected(true);
      },
    },
    { type: 'sep' },
    {
      type: 'item',
      label: 'Delete',
      shortcut: 'Delete',
      danger: true,
      disabled: !hasSelection,
      action: () => {
        ensureSelectionFromRegion();
        useBoardStore.getState().deleteSelected();
        useBoardStore.getState().updateAppState({ captureRegion: null });
      },
    },
  ];

  return (
    <div
      ref={ref}
      className="pointer-events-auto fixed z-[100] min-w-[260px] overflow-hidden rounded-lg border border-neutral-200 bg-white py-1 font-ui text-[13px] text-neutral-800 shadow-xl dark:border-neutral-700 dark:bg-[#2b2b2b] dark:text-neutral-100"
      style={{ left: pos.x || menu.x, top: pos.y || menu.y }}
      onPointerDown={(e) => e.stopPropagation()}
    >
      {items.map((item, i) => {
        if (item.type === 'sep') {
          return (
            <div
              key={`sep-${i}`}
              className="my-1 border-t border-neutral-200 dark:border-neutral-700"
            />
          );
        }
        return (
          <button
            key={`${item.label}-${i}`}
            type="button"
            disabled={item.disabled}
            onClick={() => void run(item.action)}
            className={`flex w-full items-center justify-between gap-6 px-3 py-1.5 text-left disabled:cursor-default disabled:opacity-40 ${
              item.danger
                ? 'text-red-600 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-950/40'
                : 'hover:bg-neutral-100 dark:hover:bg-neutral-700'
            }`}
          >
            <span>{item.label}</span>
            {item.shortcut && (
              <span className="shrink-0 text-[11px] text-neutral-400">{item.shortcut}</span>
            )}
          </button>
        );
      })}
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { renderScene } from '@/canvas/renderer';
import { useCanvasInteraction } from '@/hooks/useCanvasInteraction';
import { TextEditor } from '@/components/TextEditor';
import { ContextMenu, type ContextMenuState } from '@/components/ContextMenu';
import { hitTestElement, isPointInBox } from '@/utils/geometry';
import { selectElementsInRegion } from '@/utils/selectionActions';

export function CanvasBoard() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const selectionRectRef = useRef<{
    x: number;
    y: number;
    width: number;
    height: number;
  } | null>(null);
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  const setSelectionRect = (
    rect: { x: number; y: number; width: number; height: number } | null,
  ) => {
    selectionRectRef.current = rect;
  };

  const currentTool = useBoardStore((s) => s.appState.currentTool);
  const editingTextId = useBoardStore((s) => s.appState.editingTextId);

  const { onPointerDown, onPointerMove, onPointerUp, onWheel, onKeyDown, onKeyUp } =
    useCanvasInteraction(canvasRef, setSelectionRect);

  useEffect(() => {
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    };
  }, [onKeyDown, onKeyUp]);

  useEffect(() => {
    let raf = 0;
    const draw = () => {
      const canvas = canvasRef.current;
      if (canvas) {
        const state = useBoardStore.getState();
        renderScene({
          canvas,
          elements: state.elements,
          files: state.files,
          appState: state.appState,
          selectionRect: selectionRectRef.current,
          remotePointers: Object.values(state.remotePointers),
        });
      }
      raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf);
  }, []);

  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(() => setToast(null), 2000);
    return () => window.clearTimeout(t);
  }, [toast]);

  const cursor =
    currentTool === 'hand'
      ? 'grab'
      : currentTool === 'eraser'
        ? 'cell'
        : currentTool === 'text'
          ? 'text'
          : currentTool === 'region'
            ? 'crosshair'
            : currentTool === 'selection'
              ? 'default'
              : 'crosshair';

  const startEditTextAt = (clientX: number, clientY: number) => {
    const store = useBoardStore.getState();
    if (store.appState.editingTextId) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const { scrollX, scrollY, zoom } = store.appState;
    const x = (clientX - rect.left) / zoom - scrollX;
    const y = (clientY - rect.top) / zoom - scrollY;

    for (let i = store.elements.length - 1; i >= 0; i--) {
      const el = store.elements[i];
      if (el.isDeleted || el.type !== 'text' || el.locked) continue;
      if (hitTestElement(el, x, y)) {
        store.commitHistory();
        store.selectElements([el.id]);
        store.updateAppState({ editingTextId: el.id });
        return;
      }
    }
  };

  const openContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    const store = useBoardStore.getState();
    if (store.appState.editingTextId) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const { scrollX, scrollY, zoom, captureRegion } = store.appState;
    const x = (e.clientX - rect.left) / zoom - scrollX;
    const y = (e.clientY - rect.top) / zoom - scrollY;

    // Ưu tiên khung khoanh vùng
    if (captureRegion && isPointInBox({ x, y }, captureRegion)) {
      selectElementsInRegion(captureRegion);
      setContextMenu({ x: e.clientX, y: e.clientY });
      return;
    }

    // Click phải lên object → chọn object rồi mở menu
    for (let i = store.elements.length - 1; i >= 0; i--) {
      const el = store.elements[i];
      if (el.isDeleted) continue;
      if (hitTestElement(el, x, y)) {
        if (!store.appState.selectedElementIds[el.id]) {
          store.selectElements([el.id]);
        }
        setContextMenu({ x: e.clientX, y: e.clientY });
        return;
      }
    }

    // Có khung vùng / có selection sẵn → vẫn mở menu
    const hasSelection = Object.keys(store.appState.selectedElementIds).length > 0;
    if (captureRegion || hasSelection) {
      setContextMenu({ x: e.clientX, y: e.clientY });
    }
  }, []);

  return (
    <div className="absolute inset-0">
      <canvas
        ref={canvasRef}
        className="absolute inset-0 h-full w-full touch-none"
        style={{ cursor: editingTextId ? 'default' : cursor }}
        onPointerDown={editingTextId ? undefined : onPointerDown}
        onPointerMove={editingTextId ? undefined : onPointerMove}
        onPointerUp={editingTextId ? undefined : onPointerUp}
        onPointerLeave={editingTextId ? undefined : onPointerUp}
        onDoubleClick={(e) => {
          const tool = useBoardStore.getState().appState.currentTool;
          if (tool === 'selection' || tool === 'text') {
            startEditTextAt(e.clientX, e.clientY);
          }
        }}
        onWheel={onWheel}
        onContextMenu={openContextMenu}
      />
      <TextEditor />
      <ContextMenu
        menu={contextMenu}
        onClose={() => setContextMenu(null)}
        onToast={setToast}
      />
      {toast && (
        <div className="pointer-events-none absolute bottom-16 left-1/2 z-[110] -translate-x-1/2 rounded-full bg-neutral-900 px-3 py-1.5 font-ui text-xs text-white shadow-lg">
          {toast}
        </div>
      )}
    </div>
  );
}

