import { useEffect } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import type { ToolType } from '@/types';
import { getSelectedElements } from '@/utils/elements';
import { copyRegionToClipboard, getCaptureOrSelectionRegion } from '@/utils/export';
import {
  bringForward,
  copySelectedElements,
  copySelectedStyles,
  cutSelectedElements,
  flipSelected,
  pasteSelectedStyles,
  selectElementsInRegion,
  sendBackward,
} from '@/utils/selectionActions';

function notifyRegionCopy(detail: string) {
  window.dispatchEvent(new CustomEvent('region-copy-status', { detail }));
}

export function useKeyboard() {
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
        return;
      }

      const store = useBoardStore.getState();
      const meta = e.metaKey || e.ctrlKey;
      const key = e.key.toLowerCase();

      if (meta && key === 'z' && !e.shiftKey) {
        e.preventDefault();
        store.undo();
        return;
      }
      if ((meta && key === 'z' && e.shiftKey) || (meta && key === 'y')) {
        e.preventDefault();
        store.redo();
        return;
      }
      if (meta && key === 'd') {
        e.preventDefault();
        store.duplicateSelected();
        return;
      }
      if (meta && key === 'a') {
        e.preventDefault();
        const ids = store.elements.filter((el) => !el.isDeleted).map((el) => el.id);
        store.selectElements(ids);
        return;
      }
      if (meta && key === 'g' && !e.shiftKey) {
        e.preventDefault();
        store.groupSelected();
        return;
      }
      if (meta && key === 'g' && e.shiftKey) {
        e.preventDefault();
        store.ungroupSelected();
        return;
      }

      // Shift+Alt+C: copy vùng/selection thành PNG
      if (e.shiftKey && e.altKey && key === 'c') {
        e.preventDefault();
        const region = getCaptureOrSelectionRegion(
          store.elements,
          store.appState.selectedElementIds,
          store.appState.captureRegion,
        );
        if (!region) return;
        void copyRegionToClipboard(
          store.elements,
          store.files,
          store.appState.viewBackgroundColor,
          region,
        ).then((ok) => notifyRegionCopy(ok ? 'Đã copy PNG (Shift+Alt+C)' : 'Đã tải PNG'));
        return;
      }

      // Ctrl+Alt+C / Ctrl+Alt+V: copy/paste styles
      if (meta && e.altKey && key === 'c') {
        e.preventDefault();
        if (store.appState.captureRegion) selectElementsInRegion(store.appState.captureRegion);
        copySelectedStyles();
        return;
      }
      if (meta && e.altKey && key === 'v') {
        e.preventDefault();
        if (store.appState.captureRegion) selectElementsInRegion(store.appState.captureRegion);
        pasteSelectedStyles();
        return;
      }

      if (meta && key === 'x') {
        e.preventDefault();
        if (store.appState.captureRegion) selectElementsInRegion(store.appState.captureRegion);
        cutSelectedElements();
        store.updateAppState({ captureRegion: null });
        return;
      }

      if (meta && key === 'c') {
        const region = store.appState.captureRegion;
        if (region) {
          e.preventDefault();
          void copyRegionToClipboard(
            store.elements,
            store.files,
            store.appState.viewBackgroundColor,
            region,
          ).then((ok) => {
            notifyRegionCopy(
              ok ? 'Đã copy ảnh (Ctrl+C)' : 'Đã tải ảnh (trình duyệt không hỗ trợ copy)',
            );
          }).catch(() => notifyRegionCopy('Copy thất bại — thử Lưu PNG'));
          return;
        }

        const selected = getSelectedElements(store.elements, store.appState.selectedElementIds);
        if (selected.length) {
          e.preventDefault();
          copySelectedElements();
        }
        return;
      }
      // Ctrl+V ảnh xử lý ở useClipboardPaste (sự kiện paste).
      if (meta && key === 'v') {
        return;
      }

      if (meta && key === 'l' && e.shiftKey) {
        e.preventDefault();
        store.lockSelected(true);
        return;
      }

      if (meta && (e.key === '[' || e.key === '{')) {
        e.preventDefault();
        if (e.shiftKey) store.sendToBack();
        else sendBackward();
        return;
      }
      if (meta && (e.key === ']' || e.key === '}')) {
        e.preventDefault();
        if (e.shiftKey) store.bringToFront();
        else bringForward();
        return;
      }

      if (!meta && e.shiftKey && key === 'h') {
        e.preventDefault();
        flipSelected('horizontal');
        return;
      }
      if (!meta && e.shiftKey && key === 'v') {
        e.preventDefault();
        flipSelected('vertical');
        return;
