import { useEffect, useRef, useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import {
  downloadJSON,
  exportPNG,
  exportSVG,
  importJSONFile,
} from '@/utils/export';
import { connectCollaboration, disconnectCollaboration } from '@/services/collaboration';
import { createId } from '@/utils/id';
import { getSelectedElements } from '@/utils/elements';

const BG_COLORS = [
  '#ffffff',
  '#f8f9fa',
  '#f1f3f5',
  '#fff3bf',
  '#ffc9c9',
  '#eebefa',
  '#b2f2bb',
  '#a5d8ff',
  '#212529',
];

interface Props {
  open: boolean;
  onClose: () => void;
  onOpenCollab: () => void;
  onOpenExport: () => void;
  onOpenFind: () => void;
  onOpenCommands: () => void;
  importInputRef: React.RefObject<HTMLInputElement | null>;
}

export function MainMenu({
  open,
  onClose,
  onOpenCollab,
  onOpenExport,
  onOpenFind,
  onOpenCommands,
  importInputRef,
}: Props) {
  const menuRef = useRef<HTMLDivElement>(null);
  const [prefsOpen, setPrefsOpen] = useState(false);
  const [lang, setLang] = useState<'en' | 'vi'>('vi');
  const appState = useBoardStore((s) => s.appState);
  const elements = useBoardStore((s) => s.elements);
  const files = useBoardStore((s) => s.files);
  const setTheme = useBoardStore((s) => s.setTheme);
  const updateAppState = useBoardStore((s) => s.updateAppState);
  const persist = useBoardStore((s) => s.persist);
  const loadBoard = useBoardStore((s) => s.loadBoard);

  useEffect(() => {
    if (!open) {
      setPrefsOpen(false);
      return;
    }
    const onDown = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('mousedown', onDown);
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('mousedown', onDown);
      window.removeEventListener('keydown', onKey);
    };
  }, [open, onClose]);

  if (!open) return null;

  const t = (en: string, vi: string) => (lang === 'vi' ? vi : en);

  const themeMode =
    appState.theme === 'dark' ? 'dark' : 'light';

  return (
    <div
      ref={menuRef}
      className="absolute left-0 top-12 z-50 w-[300px] overflow-hidden rounded-xl border border-neutral-200 bg-white shadow-2xl dark:border-neutral-700 dark:bg-[#23232a]"
    >
      <div className="max-h-[min(80vh,640px)] overflow-y-auto py-1.5 font-ui text-[13px]">
        <MenuRow
          icon="📂"
          label={t('Open', 'Mở')}
          shortcut="Ctrl+O"
          onClick={() => {
            importInputRef.current?.click();
            onClose();
          }}
        />
        <MenuRow
          icon="💾"
          label={t('Save to...', 'Lưu vào...')}
          onClick={() => {
            persist();
            downloadJSON(elements, files, appState);
            onClose();
          }}
        />
        <MenuRow
          icon="🖼️"
          label={t('Export image...', 'Xuất ảnh...')}
          shortcut="Ctrl+Shift+E"
          onClick={() => {
            onClose();
            onOpenExport();
          }}
        />
        <MenuRow
          icon="👥"
          label={t('Live collaboration...', 'Cộng tác realtime...')}
          onClick={() => {
            onClose();
            onOpenCollab();
          }}
        />
        <MenuRow
          icon="⌘"
          label={t('Command palette', 'Bảng lệnh')}
          shortcut="Ctrl+/"
          accent
          onClick={() => {
            onClose();
            onOpenCommands();
          }}
        />
        <MenuRow
          icon="🔎"
          label={t('Find on canvas', 'Tìm trên canvas')}
          shortcut="Ctrl+F"
          onClick={() => {
            onClose();
            onOpenFind();
          }}
        />
        <MenuRow
          icon="❓"
          label={t('Help', 'Trợ giúp')}
          shortcut="?"
          onClick={() => {
            window.open('https://github.com/excalidraw/excalidraw', '_blank');
            onClose();
          }}
        />
        <MenuRow
          icon="🗑️"
          label={t('Reset the canvas', 'Xóa toàn bộ canvas')}
          onClick={() => {
            if (confirm(t('Clear the canvas?', 'Xóa hết bản vẽ?'))) {
              loadBoard({ elements: [], files: {} });
              updateAppState({ captureRegion: null, selectedElementIds: {} });
            }
            onClose();
          }}
        />

        <Sep />

        <MenuRow
          icon="✦"
          label="Excalidraw+"
          accent
          onClick={() => {
            window.open('https://plus.excalidraw.com', '_blank');
            onClose();
          }}
        />
        <MenuRow
          icon="🐙"
          label="GitHub"
          onClick={() => {
            window.open('https://github.com/excalidraw/excalidraw', '_blank');
            onClose();
          }}
        />
        <MenuRow
          icon="𝕏"
          label={t('Follow us', 'Theo dõi')}
          onClick={() => {
            window.open('https://x.com/excalidraw', '_blank');
            onClose();
          }}
        />
        <MenuRow
          icon="💬"
          label="Discord chat"
          onClick={() => {
            window.open('https://discord.gg/excalidraw', '_blank');
            onClose();
          }}
        />
        <MenuRow
          icon="👤"
