export function ExportImageModal({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  const elements = useBoardStore((s) => s.elements);
  const files = useBoardStore((s) => s.files);
  const appState = useBoardStore((s) => s.appState);
  const [format, setFormat] = useState<'png' | 'svg' | 'json'>('png');

  if (!open) return null;

  const doExport = () => {
    const selected = getSelectedElements(elements, appState.selectedElementIds);
    const region = appState.captureRegion;
    const source =
      selected.length > 0
        ? selected
        : elements.filter((e) => !e.isDeleted);

    if (format === 'png') {
      if (region) {
        import('@/utils/export').then(({ downloadRegionPNG }) => {
          void downloadRegionPNG(elements, files, appState.viewBackgroundColor, region);
        });
      } else {
        exportPNG(source, files, appState.viewBackgroundColor);
      }
    } else if (format === 'svg') {
      exportSVG(source, files, appState.viewBackgroundColor);
    } else {
      downloadJSON(elements, files, appState);
    }
    onClose();
  };

  return (
    <div className="pointer-events-auto fixed inset-0 z-[120] flex items-center justify-center bg-black/30 p-4">
      <div className="w-full max-w-md rounded-2xl bg-white p-5 shadow-2xl dark:bg-[#2a2a2a]">
        <h2 className="mb-1 font-ui text-lg font-semibold">Export image</h2>
        <p className="mb-4 font-ui text-xs text-neutral-500">
          Xuất toàn bộ canvas, vùng chọn, hoặc khung khoanh vùng hiện tại.
        </p>
        <div className="mb-4 flex gap-2">
          {(['png', 'svg', 'json'] as const).map((f) => (
            <button
              key={f}
              type="button"
              onClick={() => setFormat(f)}
              className={`flex-1 rounded-lg py-2 font-ui text-sm uppercase ${
                format === f
                  ? 'bg-accent text-white'
                  : 'bg-neutral-100 dark:bg-neutral-700'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
        <div className="flex justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg px-3 py-2 font-ui text-sm hover:bg-neutral-100 dark:hover:bg-neutral-700"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={doExport}
            className="rounded-lg bg-accent px-4 py-2 font-ui text-sm text-white hover:bg-accent-hover"
          >
            Export
          </button>
        </div>
      </div>
    </div>
  );
}

export function FindModal({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  const [q, setQ] = useState('');
  const elements = useBoardStore((s) => s.elements);
  const selectElements = useBoardStore((s) => s.selectElements);
  const setScroll = useBoardStore((s) => s.setScroll);
  const setZoom = useBoardStore((s) => s.setZoom);

  if (!open) return null;

  const matches = elements.filter(
    (el) =>
      !el.isDeleted &&
      el.type === 'text' &&
      el.text.toLowerCase().includes(q.trim().toLowerCase()),
  );

  return (
    <div className="pointer-events-auto fixed inset-0 z-[120] flex items-start justify-center bg-black/20 p-4 pt-24">
      <div className="w-full max-w-md rounded-2xl bg-white p-4 shadow-2xl dark:bg-[#2a2a2a]">
        <input
          autoFocus
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Tìm text trên canvas..."
          className="mb-3 w-full rounded-lg border border-neutral-200 bg-transparent px-3 py-2 font-ui text-sm dark:border-neutral-600"
        />
        <div className="max-h-60 space-y-1 overflow-y-auto">
          {q.trim() && matches.length === 0 && (
            <p className="px-2 py-3 font-ui text-xs text-neutral-500">Không tìm thấy</p>
          )}
          {matches.map((el) => (
            <button
              key={el.id}
              type="button"
              className="flex w-full rounded-lg px-3 py-2 text-left font-ui text-sm hover:bg-neutral-100 dark:hover:bg-neutral-700"
              onClick={() => {
                selectElements([el.id]);
                setZoom(1);
                setScroll(-el.x + window.innerWidth / 2 / 1 - 100, -el.y + window.innerHeight / 2 - 80);
                onClose();
              }}
            >
              {el.type === 'text' ? el.text.slice(0, 80) : el.id}
            </button>
          ))}
        </div>
        <button
          type="button"
          onClick={onClose}
          className="mt-3 w-full rounded-lg py-2 font-ui text-sm text-neutral-500 hover:bg-neutral-100 dark:hover:bg-neutral-700"
        >
          Đóng
        </button>
      </div>
    </div>
  );
}

export function CommandPalette({
  open,
  onClose,
  onAction,
}: {
  open: boolean;
  onClose: () => void;
  onAction: (id: string) => void;
}) {
  const [q, setQ] = useState('');
  if (!open) return null;

  const commands = [
    { id: 'export', label: 'Export image...', shortcut: 'Ctrl+Shift+E' },
    { id: 'open', label: 'Open file', shortcut: 'Ctrl+O' },
    { id: 'save', label: 'Save JSON', shortcut: '' },
    { id: 'collab', label: 'Live collaboration', shortcut: '' },
    { id: 'find', label: 'Find on canvas', shortcut: 'Ctrl+F' },
    { id: 'theme', label: 'Toggle theme', shortcut: '' },
    { id: 'reset', label: 'Reset the canvas', shortcut: '' },
    { id: 'grid', label: 'Toggle grid', shortcut: '' },
  ].filter((c) => c.label.toLowerCase().includes(q.toLowerCase()));

  return (
    <div className="pointer-events-auto fixed inset-0 z-[120] flex items-start justify-center bg-black/25 p-4 pt-28">
      <div className="w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-2xl dark:bg-[#2a2a2a]">
        <input
          autoFocus
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Type a command..."
          className="w-full border-b border-neutral-200 bg-transparent px-4 py-3 font-ui text-sm outline-none dark:border-neutral-700"
          onKeyDown={(e) => {
            if (e.key === 'Escape') onClose();
            if (e.key === 'Enter' && commands[0]) {
              onAction(commands[0].id);
              onClose();
            }
          }}
        />
        <div className="max-h-72 overflow-y-auto py-1">
          {commands.map((c) => (
            <button
              key={c.id}
              type="button"
              className="flex w-full items-center justify-between px-4 py-2.5 text-left font-ui text-sm hover:bg-accent/10"
              onClick={() => {
                onAction(c.id);
                onClose();
              }}
            >
              <span>{c.label}</span>
              {c.shortcut && <span className="text-[11px] text-neutral-400">{c.shortcut}</span>}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

