import { useEffect, useRef, useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import { Icons } from './icons';
import { downloadJSON, importJSONFile } from '@/utils/export';
import { connectCollaboration, disconnectCollaboration } from '@/services/collaboration';
import { createId } from '@/utils/id';
import {
  CommandPalette,
  ExportImageModal,
  FindModal,
  MainMenu,
} from './MainMenu';

export function TopBar() {
  const appState = useBoardStore((s) => s.appState);
  const updateAppState = useBoardStore((s) => s.updateAppState);
  const setTheme = useBoardStore((s) => s.setTheme);
  const loadBoard = useBoardStore((s) => s.loadBoard);
  const persist = useBoardStore((s) => s.persist);
  const elements = useBoardStore((s) => s.elements);
  const files = useBoardStore((s) => s.files);
  const collaborators = useBoardStore((s) => s.collaborators);

  const importRef = useRef<HTMLInputElement>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [collabOpen, setCollabOpen] = useState(false);
  const [exportOpen, setExportOpen] = useState(false);
  const [findOpen, setFindOpen] = useState(false);
  const [commandsOpen, setCommandsOpen] = useState(false);
  const [roomInput, setRoomInput] = useState('');

  const onImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    try {
      const doc = await importJSONFile(file);
      loadBoard({
        elements: doc.elements,
        files: doc.files,
        appState: doc.appState,
      });
    } catch (err) {
      alert(err instanceof Error ? err.message : 'Import thất bại');
    }
  };

  const startCollab = () => {
    const roomId = roomInput.trim() || createId('room');
    setRoomInput(roomId);
    connectCollaboration(roomId);
    setCollabOpen(false);
  };

  const runCommand = (id: string) => {
    switch (id) {
      case 'export':
        setExportOpen(true);
        break;
      case 'open':
        importRef.current?.click();
        break;
      case 'save':
        persist();
        downloadJSON(elements, files, appState);
        break;
      case 'collab':
        setCollabOpen(true);
        break;
      case 'find':
        setFindOpen(true);
        break;
      case 'theme':
        setTheme(appState.theme === 'dark' ? 'light' : 'dark');
        break;
      case 'reset':
        if (confirm('Xóa hết bản vẽ?')) {
          loadBoard({ elements: [], files: {} });
        }
        break;
      case 'grid':
        updateAppState({ gridMode: !appState.gridMode });
        break;
      default:
        break;
    }
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
        return;
      }
      const meta = e.metaKey || e.ctrlKey;
      if (meta && e.shiftKey && e.key.toLowerCase() === 'e') {
        e.preventDefault();
        setExportOpen(true);
        return;
      }
      if (meta && e.key.toLowerCase() === 'o') {
        e.preventDefault();
        importRef.current?.click();
        return;
      }
      if (meta && e.key === '/') {
        e.preventDefault();
        setCommandsOpen(true);
        return;
      }
      if (meta && e.key.toLowerCase() === 'f') {
        e.preventDefault();
        setFindOpen(true);
        return;
      }
      if (e.key === '?' && !meta && !e.altKey) {
        // Help tip
        setCommandsOpen(true);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const collabCount = Object.keys(collaborators).length;

  return (
    <>
      <header className="pointer-events-none absolute inset-x-0 top-0 z-30 flex items-start justify-between gap-3 p-3">
        <div className="pointer-events-auto relative flex items-center gap-2">
          <div className="relative flex items-center gap-1 rounded-xl bg-white/95 p-1 shadow-toolbar backdrop-blur dark:bg-[#2a2a2a]/95">
            <button
              type="button"
              title="Menu"
              onClick={() => setMenuOpen((v) => !v)}
              className={`flex h-9 w-9 items-center justify-center rounded-lg ${
                menuOpen
                  ? 'bg-accent text-white'
                  : 'text-neutral-700 hover:bg-neutral-100 dark:text-neutral-200 dark:hover:bg-neutral-700'
              }`}
            >
              <HamburgerIcon />
            </button>
          </div>

          <MainMenu
            open={menuOpen}
            onClose={() => setMenuOpen(false)}
            onOpenCollab={() => setCollabOpen(true)}
            onOpenExport={() => setExportOpen(true)}
            onOpenFind={() => setFindOpen(true)}
            onOpenCommands={() => setCommandsOpen(true)}
            importInputRef={importRef}
          />
        </div>

        <div className="pointer-events-auto flex items-center gap-2">
          <div className="relative">
            <button
              type="button"
              onClick={() => setCollabOpen((v) => !v)}
              className="flex items-center gap-2 rounded-xl bg-accent px-3 py-2 font-ui text-sm font-medium text-white shadow-toolbar hover:bg-accent-hover"
            >
              <Icons.Users />
              Live
              {appState.roomId && (
                <span className="rounded-full bg-white/20 px-2 py-0.5 text-[10px]">
                  {Math.max(collabCount, 1)}
                </span>
              )}
            </button>
            {collabOpen && (
              <div className="absolute right-0 top-12 w-72 rounded-xl border border-neutral-200 bg-white p-3 shadow-lg dark:border-neutral-700 dark:bg-[#2a2a2a]">
                <p className="mb-2 font-ui text-xs text-neutral-500">
                  Nhập mã phòng để cộng tác realtime.
                </p>
                <input
                  value={roomInput || appState.roomId || ''}
                  onChange={(e) => setRoomInput(e.target.value)}
                  placeholder="room-id"
                  className="mb-2 w-full rounded-md border border-neutral-300 bg-transparent px-2 py-1.5 font-ui text-sm dark:border-neutral-600"
                />
                <div className="mb-2">
                  <label className="font-ui text-[10px] text-neutral-500">Tên của bạn</label>
                  <input
                    value={appState.userName}
                    onChange={(e) => updateAppState({ userName: e.target.value })}
                    className="w-full rounded-md border border-neutral-300 bg-transparent px-2 py-1.5 font-ui text-sm dark:border-neutral-600"
                  />
                </div>
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={startCollab}
                    className="flex-1 rounded-md bg-accent px-2 py-1.5 font-ui text-sm text-white"
                  >
                    {appState.roomId ? 'Rejoin' : 'Join'}
                  </button>
                  {appState.roomId && (
                    <button
                      type="button"
                      onClick={() => {
                        disconnectCollaboration();
                        setCollabOpen(false);
                      }}
