import { useRef, useState } from 'react';
import { useBoardStore } from '@/store/useBoardStore';
import type { ToolType } from '@/types';
import { Icons } from './icons';
import { insertImageFromFile } from '@/utils/imageInsert';

type ToolItem = {
  id: ToolType;
  label: string;
  icon: keyof typeof Icons;
  shortcut?: string;
};

const mainTools: ToolItem[] = [
  { id: 'selection', label: 'Selection', icon: 'Selection', shortcut: '1' },
  { id: 'rectangle', label: 'Rectangle', icon: 'Rectangle', shortcut: '2' },
  { id: 'diamond', label: 'Diamond', icon: 'Diamond', shortcut: '3' },
  { id: 'ellipse', label: 'Ellipse', icon: 'Ellipse', shortcut: '4' },
  { id: 'arrow', label: 'Arrow', icon: 'Arrow', shortcut: '5' },
  { id: 'line', label: 'Line', icon: 'Line', shortcut: '6' },
  { id: 'freedraw', label: 'Draw', icon: 'Pencil', shortcut: '7' },
  { id: 'text', label: 'Text', icon: 'Text', shortcut: '8' },
  { id: 'image', label: 'Image', icon: 'Image', shortcut: '9' },
  { id: 'eraser', label: 'Eraser', icon: 'Eraser', shortcut: '0' },
];

const extraTools: ToolItem[] = [
  { id: 'region', label: 'Khoanh vùng → ảnh', icon: 'Region', shortcut: 'S' },
];

export function Toolbar() {
  const currentTool = useBoardStore((s) => s.appState.currentTool);
  const activeToolLocked = useBoardStore((s) => s.appState.activeToolLocked);
  const setTool = useBoardStore((s) => s.setTool);
  const updateAppState = useBoardStore((s) => s.updateAppState);
  const fileRef = useRef<HTMLInputElement>(null);
  const [moreOpen, setMoreOpen] = useState(false);

  const onToolClick = (tool: ToolType) => {
    if (tool === 'image') {
      fileRef.current?.click();
      return;
    }
    setTool(tool);
    setMoreOpen(false);
  };

  const onImageSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    await insertImageFromFile(file);
  };

  return (
    <div className="pointer-events-none absolute inset-x-0 top-3 z-20 flex justify-center px-3">
      <div className="pointer-events-auto relative flex max-w-[calc(100vw-1.5rem)] items-center gap-1 overflow-x-auto rounded-xl bg-white/95 p-1.5 shadow-toolbar backdrop-blur dark:bg-[#2a2a2a]/95">
        {/* Lock keep tool */}
        <ToolBtn
          title="Keep selected tool active"
          active={activeToolLocked}
          onClick={() => updateAppState({ activeToolLocked: !activeToolLocked })}
        >
          <Icons.Lock />
        </ToolBtn>

        <ToolBtn
          title="Hand (H) — pan canvas"
          active={currentTool === 'hand'}
          onClick={() => setTool('hand')}
        >
          <Icons.Hand />
        </ToolBtn>

        <Divider />

        {mainTools.map((tool) => {
          const Icon = Icons[tool.icon];
          const active = currentTool === tool.id;
          return (
            <ToolBtn
              key={tool.id}
              title={`${tool.label}${tool.shortcut ? ` (${tool.shortcut})` : ''}`}
              active={active}
              badge={tool.shortcut}
              onClick={() => onToolClick(tool.id)}
            >
              <Icon />
            </ToolBtn>
          );
        })}

        <Divider />

        <div className="relative">
          <ToolBtn
            title="More tools"
            active={moreOpen || extraTools.some((t) => t.id === currentTool)}
            onClick={() => setMoreOpen((v) => !v)}
          >
            <Icons.More />
          </ToolBtn>
          {moreOpen && (
            <div className="absolute left-1/2 top-12 z-40 min-w-[200px] -translate-x-1/2 rounded-xl border border-neutral-200 bg-white p-1 shadow-lg dark:border-neutral-700 dark:bg-[#2a2a2a]">
              {extraTools.map((tool) => {
                const Icon = Icons[tool.icon];
                return (
                  <button
                    key={tool.id}
                    type="button"
                    onClick={() => onToolClick(tool.id)}
                    className={`flex w-full items-center gap-2 rounded-lg px-3 py-2 font-ui text-sm ${
                      currentTool === tool.id
                        ? 'bg-accent/15 text-accent'
                        : 'hover:bg-neutral-100 dark:hover:bg-neutral-700'
                    }`}
                  >
                    <Icon />
                    <span className="flex-1 text-left">{tool.label}</span>
                    {tool.shortcut && (
                      <span className="text-[11px] text-neutral-400">{tool.shortcut}</span>
                    )}
                  </button>
                );
              })}
            </div>
          )}
        </div>
      </div>

      <input
        ref={fileRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={onImageSelected}
      />
    </div>
  );
}

function Divider() {
  return <div className="mx-0.5 h-7 w-px shrink-0 bg-neutral-200 dark:bg-neutral-600" />;
}

function ToolBtn({
  children,
  onClick,
  title,
  active,
  badge,
}: {
  children: React.ReactNode;
  onClick: () => void;
  title: string;
  active?: boolean;
  badge?: string;
}) {
  return (
    <button
      type="button"
      title={title}
      onClick={onClick}
      className={`relative flex h-10 w-10 shrink-0 items-center justify-center rounded-lg transition ${
        active
          ? 'bg-accent/15 text-accent'
          : 'text-neutral-700 hover:bg-neutral-100 dark:text-neutral-200 dark:hover:bg-neutral-700'
      }`}
    >
      {children}
      {badge && (
        <span className="pointer-events-none absolute bottom-0.5 right-1 font-ui text-[9px] leading-none text-neutral-400">
          {badge}
        </span>
      )}
    </button>
  );
}

