    stroke: element.strokeColor,
    strokeWidth: element.strokeWidth,
    fill: bg,
    fillStyle: 'solid',
  });
  // thanh tiêu đề mỏng
  ctx.fillStyle = 'rgba(0,0,0,0.06)';
  ctx.fillRect(element.x + 2, element.y + 2, Math.max(0, element.width - 4), 18);

  ctx.fillStyle = element.strokeColor;
  ctx.font = `${element.fontSize}px ${element.fontFamily}`;
  ctx.textBaseline = 'top';
  const maxW = Math.max(20, element.width - pad * 2);
  const lineH = element.fontSize * 1.4;
  const startY = element.y + 28;
  const maxY = element.y + element.height - pad;
  const wrapped = wrapTextLines(ctx, element.text || '', maxW);
  let y = startY;
  for (const line of wrapped) {
    if (y + lineH > maxY) {
      ctx.fillText('…', element.x + pad, y);
