import { useBoardStore } from '@/store/useBoardStore';

/** Zoom canvas về phía điểm chuột (clientX/Y), dùng chung cho canvas và khi đang edit notepad */
export function zoomAtClientPoint(
  clientX: number,
  clientY: number,
  deltaY: number,
  canvasEl?: HTMLElement | null,
) {
  const store = useBoardStore.getState();
  const canvas =
    canvasEl ??
    (document.querySelector('canvas') as HTMLCanvasElement | null);
  if (!canvas) return;

  const rect = canvas.getBoundingClientRect();
  const { zoom, scrollX, scrollY } = store.appState;
  const mouseX = clientX - rect.left;
  const mouseY = clientY - rect.top;
  const sceneX = mouseX / zoom - scrollX;
  const sceneY = mouseY / zoom - scrollY;
  const factor = deltaY > 0 ? 0.9 : 1.1;
  const nextZoom = Math.min(8, Math.max(0.1, zoom * factor));
  store.setZoom(nextZoom);
  store.setScroll(mouseX / nextZoom - sceneX, mouseY / nextZoom - sceneY);
}

export function panByWheel(deltaX: number, deltaY: number) {
  const store = useBoardStore.getState();
  store.setScroll(
    store.appState.scrollX - deltaX / store.appState.zoom,
    store.appState.scrollY - deltaY / store.appState.zoom,
  );
}

