export function hitTestHandle(
  element: ExcalidrawElement,
  x: number,
  y: number,
): string | null {
  const center = getElementCenter(element);
  let px = x;
  let py = y;
  if (element.angle) {
    const r = rotatePoint({ x, y }, center, -element.angle);
    px = r.x;
    py = r.y;
  }
  for (const h of getResizeHandles(element)) {
    if (Math.abs(px - h.x) <= 8 && Math.abs(py - h.y) <= 8) return h.id;
  }
  return null;
}

input.new_string:
export function hitTestHandle(
  element: ExcalidrawElement,
  x: number,
  y: number,
  zoom = 1,
): string | null {
  const center = getElementCenter(element);
  let px = x;
  let py = y;
  if (element.angle) {
    const r = rotatePoint({ x, y }, center, -element.angle);
    px = r.x;
    py = r.y;
  }
  // ~14px trên màn hình, không phụ thuộc zoom (trước đây 8 scene-px → khó bấm khi zoom nhỏ)
  const pad = Math.max(12, 14 / Math.max(0.05, zoom));
  let best: string | null = null;
  let bestDist = Infinity;
  for (const h of getResizeHandles(element)) {
    const dist = Math.hypot(px - h.x, py - h.y);
    if (dist <= pad && dist < bestDist) {
      bestDist = dist;
      best = h.id;
    }
  }
  return best;
}

