    // Ảnh: giữ tỉ lệ khi kéo góc (trừ khi giữ Shift để tự do)
    const el = selected[0];
    const corner = ['nw', 'ne', 'sw', 'se'].includes(r.resizeHandle);
    const keepAspect =
      el.type === 'image' || el.type === 'note'
        ? corner && !e.shiftKey
        : e.shiftKey && corner;
    const next = resizeElement(el, r.resizeHandle, dx, dy, keepAspect);
    store.updateElement(el.id, () => next, false);
  }
  r.lastScene = scene;
  return;
}

